INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-25', '출애굽기', '11장 1절~10절', '', '(출애굽기 11장)
1.  여호와께서 모세에게 이르시기를 내가 이제 한 가지 재앙을 바로와 애굽에 내린 후에야 그가 너희를 여기서 내보내리라 그가 너희를 내보낼 때에는 여기서 반드시 다 쫓아내리니
2. 백성에게 말하여 사람들에게 각기 이웃들에게 은금 패물을 구하게 하라 하시더니
3. 여호와께서 그 백성으로 애굽 사람의 은혜를 받게 하셨고 또 그 사람 모세는 애굽 땅에 있는 바로의 신하와 백성의 눈에 아주 위대하게 보였더라
4. 모세가 바로에게 이르되 여호와께서 이와 같이 말씀하시기를 밤중에 내가 애굽 가운데로 들어가리니
5. 애굽 땅에 있는 모든 처음 난 것은 왕위에 앉아 있는 바로의 장자로부터 맷돌 뒤에 있는 몸종의 장자와 모든 가축의 처음 난 것까지 죽으리니
6. 애굽 온 땅에 전무후무한 큰 부르짖음이 있으리라
7. 그러나 이스라엘 자손에게는 사람에게나 짐승에게나 개 한 마리도 그 혀를 움직이지 아니하리니 여호와께서 애굽 사람과 이스라엘 사이를 구별하는 줄을 너희가 알리라 하셨나니
8. 왕의 이 모든 신하가 내게 내려와 내게 절하며 이르기를 너와 너를 따르는 온 백성은 나가라 한 후에야 내가 나가리라 하고 심히 노하여 바로에게서 나오니라
9. 여호와께서 모세에게 이르시기를 바로가 너희의 말을 듣지 아니하리라 그러므로 내가 애굽 땅에서 나의 기적을 더하리라 하셨고
10. 모세와 아론이 이 모든 기적을 바로 앞에서 행하였으나 여호와께서 바로의 마음을 완악하게 하셨으므로 그가 이스라엘 자손을 그 나라에서 보내지 아니하였더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2025년 1월25일 출애굽기 11장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
처음 난 것/장자: 5절 (3)
기적: 9절 10절
완악/말을 듣지않음: 9절 10절
보냄: 1절(3) 
구별(죽음/보호): 5절 7절 

4.주제만들기: 
처음 난 것의 죽음 예고(10번째 재앙)

5.하나님 찾기 (관찰)
모세로 바로에게 대언을 명령하시는 여호와.
은혜를 주시는 여호와.(애굽 신하와 백성들이 모세를 위대하게 여김)
기적을 행하시는 여호와.

6.인간 찾기(관찰)
여호와의 명령을 받들어 바로에게 대언하는 모세.
모세를 위대하게 여기는 바로 신하들과 애굽 백성들.
끝까지 완강함으로 거절하는 바로.

7.하나님 찾기(해석)

8.인간 찾기 (해석)
흑암의 9번째 재앙이 끝날 때 바로 왕은 모세를 향하여 눈에 보이면 모세를 죽인다고 협박했었다. 

하지만 10번째 마지막 재앙을 계획하신 하나님은 모세에게 담대함만 주시지 않으시고 특별한 은혜도 주셨다. 

그것은 애굽 백성과 왕의 신하들 마음에 모세를 위대하게 받아들일 수가 있는 마음을 주신 것이다. 덕분에 모세는 또다시 바로를 만나서 하나님 말씀을 선포하였다. 

그런데도 바로는 마음이 완악하여 또다시 거절하였다. 수많은 하나님의 기적을 체험해도 바로의 마음은 그의 신하들과 비교할 수 없는 바벨탑을 높이 세웠다. 

끝까지 은혜를 거부하는 불쌍한 영혼을 본다. 세상에서 아무리 부귀영화를 가졌다고 하더라도 하나님을 거역하는 인생은 결국 허무하게 무너질 수밖에 없는 것이다. 

하나님은 어쩌면 바로의 최측근 신하들을 통하여 기회를 주신 것인데 바로는 기회를 받아들이지 못함이 너무 안타깝고 우둔해 보인다.

9.적용(나):
생명의 근원이 마음에서 오고 무엇보다 그 것을 지키는 것이 중요함으로 더욱 힘써야겠다.

10. 영적터치 (단어 또는 구절)
1절: 반드시 쫓아내리라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-26', '출애굽기', '12장 1절~10절', '', '(출애굽기 12장)
1.  여호와께서 애굽 땅에서 모세와 아론에게 일러 말씀하시되
2. 이 달을 너희에게 달의 시작 곧 해의 첫 달이 되게 하고
3. 너희는 이스라엘 온 회중에게 말하여 이르라 이 달 열흘에 너희 각자가 어린 양을 취할지니 각 가족대로 그 식구를 위하여 어린 양을 취하되
4. 그 어린 양에 대하여 식구가 너무 적으면 그 집의 이웃과 함께 사람 수를 따라서 하나를 취하며 각 사람이 먹을 수 있는 분량에 따라서 너희 어린 양을 계산할 것이며
5. 너희 어린 양은 흠 없고 일 년 된 수컷으로 하되 양이나 염소 중에서 취하고
6. 이 달 열나흗날까지 간직하였다가 해 질 때에 이스라엘 회중이 그 양을 잡고
7. 그 피를 양을 먹을 집 좌우 문설주와 인방에 바르고
8. 그 밤에 그 고기를 불에 구워 무교병과 쓴 나물과 아울러 먹되
9. 날것으로나 물에 삶아서 먹지 말고 머리와 다리와 내장을 다 불에 구워 먹고
10. 아침까지 남겨두지 말며 아침까지 남은 것은 곧 불사르라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
