1:감동받는 단어나 구절 찾기(영적터치)

2025년 1월26일 출애굽기 12장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
어린양: 3절(2) 4절(2) 5절(2) 6절 7절
취할: 3절 4절
먹고/먹되: 8절 9절

4.주제만들기: 
유월절 어린양

5.하나님 찾기 (관찰)
모세와 아론에게 유월절 어린양을 취하는 방법을 알려주시는 하나님.

6.인간 찾기(관찰)
유월절 어린양 관련 여호와의 명령을 듣고 있는 모세와 아론. 

7.하나님 찾기(해석)
하나님은 9가지 재앙 후에 마지막으로 애굽 왕 바로를 포함하여 백성들에게 이르기까지 모든 장자를 취하시려는 방법을 정하셨다. 

이 끔찍한 재앙은 이스라엘 백성도 예외는 아니다. 다만 누구든지 장자를 잃고 싶지 않는다면 어린양 피(염소 피 포함)를 문설주 와 인방에 바르도록 조건을 하나님은 이미 세우셨다. 

영적으로 보면 하나님의 구원 역사와 방법을 알 수 있다. 인류의 구원자 어린양 예수의 십자가 그리고 보혈의 피에 대한 예표이다. 

하나님은 바로의 마음을 완악하게 허락하신 이유 중 하나로 십자가 보혈 밖에는 인류를 구원하심이 절대적인 것을 보여준다. 

하나님을 거역하면 죽음이라는 공의와 동시에 어린양 피를 받아들이는 백성은  생명과 자유가  주어짐을 보여준다. 

하나님의 통치에 있는 백성은 어떠한 세상의 억압받는 환경에 있더라도 자유인이고 그렇지 않은 바로처럼 반항하는 사람은 비록 세상에서 높은 위치에 있더라도 영적으로는 노예처럼 영혼이 자유롭지 못함을 일깨워 준다.

8.인간 찾기 (해석)

9.적용(나):
어린양 예수님의 공로를 더욱 묵상하며 감사의 시간을 가져야겠다.

10. 영적터치 (단어 또는 구절)
7절: 그 피를 양을 먹을 집 좌우 문설주와 인방에 바르고

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-27', '출애굽기', '12장 11절~20절', '유월절과 무교절', '[출12:11-20]
11 너희는 그것을 이렇게 먹을지니 허리에 띠를 띠고 발에 신을 신고 손에 지팡이를 잡고 급히 먹으라 이것이 여호와의 유월절이니라
12 내가 그 밤에 애굽 땅에 두루 다니며 사람이나 짐승을 막론하고 애굽 땅에 있는 모든 처음 난 것을 다 치고 애굽의 모든 신을 내가 심판하리라 나는 여호와라
13 내가 애굽 땅을 칠 때에 그 피가 너희가 사는 집에 있어서 너희를 위하여 표적이 될지라 내가 피를 볼 때에 너희를 넘어가리니 재앙이 너희에게 내려 멸하지 아니하리라
14 너희는 이 날을 기념하여 여호와의 절기를 삼아 영원한 규례로 대대로 지킬지니라
15 너희는 이레 동안 무교병을 먹을지니 그 첫날에 누룩을 너희 집에서 제하라 무릇 첫날부터 일곱째 날까지 유교병을 먹는 자는 이스라엘에서 끊어지리라
16 너희에게 첫날에도 성회요 일곱째 날에도 성회가 되리니 너희는 이 두 날에는 아무 일도 하지 말고 각자의 먹을 것만 갖출 것이니라
17 너희는 무교절을 지키라 이 날에 내가 너희 군대를 애굽 땅에서 인도하여 내었음이니라 그러므로 너희가 영원한 규례로 삼아 대대로 이 날을 지킬지니라
18 첫째 달 그 달 열나흗날 저녁부터 이십일일 저녁까지 너희는 무교병을 먹을 것이요
19 이레 동안은 누룩이 너희 집에서 발견되지 아니하도록 하라 무릇 유교물을 먹는 자는 타국인이든지 본국에서 난 자든지를 막론하고 이스라엘 회중에서 끊어지리니
20 너희는 아무 유교물이든지 먹지 말고 너희 모든 유하는 곳에서 무교병을 먹을지니라
