1. 1분기도
2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 애굽(12,13,17절)
- 피(13절)
- 지키라(14,17절)
- 무교병((15,18,20절)
- 영원한규례(14,17절)
- 누룩(15,19절)
4. 주제만들기: 유월절과 무교절
5. 하나님 찾기 (관찰)
- 유월절과 무교절에 대해 말씀하시는 하나님
6. 인간 찾기 (관찰)
7. 하나님 찾기 (해석) 
- 하나님은 유월절을 기념하라 말씀하셨다. 하나님은 애굽에서 처음 난 것을 다 치셨으나, 문설주에 피를 발라 이스라엘 백성은 살려주셨다. 어린 양의 피는 구원의 표적이 되는데, 구약에서 어린 양의 피로 이스라엘 백성이 구원 받았듯이 신약에서 예수님을 피 흘리심을 통해 전 인류에 구원의 역사가 이루어졌다. 우리가 잊지 말아야할 사실이다.
- 하나님은 무교절도 강조하셨다. 누룩을 제거하는 것은 우리의 죄를 없애는 것과 같다. 누룩은 눈에 잘 보이지 않으며, 소량으로 전체에 퍼지는 영향을 미친다. 누룩은 완전히 제거하는 것은 거룩함을 유지하려는 것이다. 애굽 사회에 물들여져 있던 이스라엘 백성은 수많은 죄 가운데 노출 되었을 것이다. 그것으로부터 완전히 벗어날 수 있도록 길을 안내해주신 것이다.
- 무교절 첫날과 마지막 날은 거룩하게 지키게 하셨는데, 우리의 신앙생활을 생각하게 된다. 하나님을 향한 첫 사랑은 마지막 날까지 동일해야 한다. 첫 사랑을 지키는 것이 참 어렵다. 수많은 유혹이 있고, 태만해지기 싶고, 교만해지도 한다. 그러나 하나님께선 처음부터 끝까지 동일하게 거룩함을 원하신다.
8. 인간(해석):
9. 적용(나): 
- 하나님이신 예수님께서 직접 이 땅에 오셔서 유월절의 어린양이 되어 피 흘리심으로 우리를 구원하신 것을 감사하며 그 사랑을 잊지 않고, 처음과 끝이 동일한 사람이 되도록 기도한다.
- 하나님의 사랑을 더욱 힘써 전해야겠다.
10. 영적터치(단어/구절)
- 피, 누룩
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-28', '출애굽기', '12장 21절~30절', '애굽에 열 번째 재앙이 임하다', '출애굽기 12장
21 모세가 이스라엘 모든 장로를 불러서 그들에게 이르되 너희는 나가서 너희의 가족대로 어린 양을 택하여 유월절 양으로 잡고
22 우슬초 묶음을 가져다가 그릇에 담은 피에 적셔서 그 피를 문 인방과 좌우 설주에 뿌리고 아침까지 한 사람도 자기 집 문 밖에 나가지 말라
23 여호와께서 애굽 사람들에게 재앙을 내리려고 지나가실 때에 문 인방과 좌우 문설주의 피를 보시면 여호와께서 그 문을 넘으시고 멸하는 자에게 너희 집에 들어가서 너희를 치지 못하게 하실 것임이니라
24 너희는 이 일을 규례로 삼아 너희와 너희 자손이 영원히 지킬 것이니
25 너희는 여호와께서 허락하신 대로 너희에게 주시는 땅에 이를 때에 이 예식을 지킬 것이라
26 이 후에 너희의 자녀가 묻기를 이 예식이 무슨 뜻이냐 하거든
27 너희는 이르기를 이는 여호와의 유월절 제사라 여호와께서 애굽 사람에게 재앙을 내리실 때에 애굽에 있는 이스라엘 자손의 집을 넘으사 우리의 집을 구원하셨느니라 하라 하매 백성이 머리 숙여 경배하니라
28 이스라엘 자손이 물러가서 그대로 행하되 여호와께서 모세와 아론에게 명령하신 대로 행하니라
29 밤중에 여호와께서 애굽 땅에서 모든 처음 난 것 곧 왕위에 앉은 바로의 장자로부터 옥에 갇힌 사람의 장자까지와 가축의 처음 난 것을 다 치시매
30 그 밤에 바로와 그 모든 신하와 모든 애굽 사람이 일어나고 애굽에 큰 부르짖음이 있었으니 이는 그 나라에 죽임을 당하지 아니한 집이 하나도 없었음이었더라

3:하나님, 인간, 나
