2025년 1월 28일 출애굽기 12장 21~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
모세: 21, 28
이스라엘: 21, 27
어린 양: 21
유월절: 21, 27
피: 22, 23
문 인방과 좌우 (문)설주: 22, 23
집: 22, 23, 27(2), 30
여호와: 23(2), 25, 27(2), 29
애굽 사람: 23, 27, 30
예식: 25, 26
애굽: 27, 29, 30
자손: 27, 28
장자: 29(2)
처음 난 것: 29(2)
바로: 29, 30
4.주제 만들기: 애굽에 열 번째 재앙이 임하다 
5.하나님 찾기 (관찰)
- 밤 중에 애굽의 모든 처음 난 것을 죽이심
6.인간 찾기 (관찰)
- 모세가 이스라엘 모든 장로를 불러, 
- 가족마다 어린 양을 유월절 양을 잡고 그 피를 문 인방과 좌우 설주에 바르고
- 아침까지 문밖으로 나가지 말 것을 명함
- 하나님께서 애굽에 재앙을 내리실 때
- 그 피를 보고 지나가실 것인데,
- 이것을 규례로 삼아 영원히 지키라고 명함
- 이스라엘 자손이 모세와 아론의 말대로 행함
- 여호와께서 애굽을 치신 후에 바로와 모든 애굽 사람이 일어나 크게 울부짖었으니,
- 애굽에 죽임을 당하지 않은 집이 하나도 없었다.
7.하나님 찾기 (해석) 
- 애굽 모든 집의 장자를 죽이시되,
- 하나님의 명령대로 행한 이스라엘 백성의 모든 집은 넘어가심
- 말씀에 순종하는 자에게 구원을 베푸심 
8.인간(해석)
- 이스라엘 백성들은 문 인방과 설주에 어린 양의 피를 바르면서,
- 그리고 애굽 모든 집의 곡소리를 들으면서,
- 어린 양이 대신 죽음으로,
- 나의 죽음은 지나가는구나 정말 다행이다라고 생각했을 것이다
- 그리고 동시에 하나님은 인간의 죽음과 
- 구원을 결정하는 분이라는 것을 깊이 깨달았을 것이다
- 규례를 지키게 함으로써 하나님의 구원과 위대하심을 
- 대대로 기념하며 기억하게 함
- 애굽 모든 사람들은 장자가 죽으므로 울부짖으면서 
- 하나님이 생명의 주관자이심을 깨닫고
- 두려웠을 것이다
- 애굽 모든 집이 죽임을 당한 것으로 보아,
- 이스라엘 백성처럼 어린 양의 피를 바르고 구원받은 집은 없다는 것을 알 수 있음 
9.적용(나)
- 어린 양의 피를 뿌리라는 하나님의 말씀에, 
- 믿음으로 반응하여 구원받은 이스라엘 백성을 통해,
- 나도 믿음으로 반응해야 함을 깨닫는다.
- 지금 나는 이스라엘 백성처럼 어린 양의 피를 바르지 않아도 된다.
- 왜냐하면 예수님께서 직접 피를 흘려 주셨기 때문이다.
- 피를 뿌리는 믿음의 행위가 필요하다면, 
- 그것은 대신하여 피를 흘리신 예수님을 믿고 사랑하는 것, 그것뿐이다.
- 유월절은 오늘날 부활절이 되었다.
- 하나님의 크신 은혜에 감사하며, 기념해야 한다. 
10. 영적터치(단어/구절) 
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-29', '출애굽기', '12장 31절~40절', '하나님의 일하시', '[출12:31-40]
31 밤에 바로가 모세와 아론을 불러서 이르되 너희와 이스라엘 자손은 일어나 내 백성 가운데에서 떠나 너희의 말대로 가서 여호와를 섬기며
32 너희가 말한 대로 너희 양과 너희 소도 몰아가고 나를 위하여 축복하라 하며
33 애굽 사람들은 말하기를 우리가 다 죽은 자가 되도다 하고 그 백성을 재촉하여 그 땅에서 속히 내보내려 하므로
34 그 백성이 발교되지 못한 반죽 담은 그릇을 옷에 싸서 어깨에 메니라
35 이스라엘 자손이 모세의 말대로 하여 애굽 사람에게 은금 패물과 의복을 구하매
36 여호와께서 애굽 사람들에게 이스라엘 백성에게 은혜를 입히게 하사 그들이 구하는 대로 주게 하시므로 그들이 애굽 사람의 물품을 취하였더라
37 이스라엘 자손이 라암셋을 떠나서 숙곳에 이르니 유아 외에 보행하는 장정이 육십만 가량이요
38 수많은 잡족과 양과 소와 심히 많은 가축이 그들과 함께 하였으며
39 그들이 애굽으로부터 가지고 나온 발교되지 못한 반죽으로 무교병을 구웠으니 이는 그들이 애굽에서 쫓겨나므로 지체할 수 없었음이며 아무 양식도 준비하지 못하였음이었더라
40 이스라엘 자손이 애굽에 거주한 지 사백삼십 년이라

3:하나님, 인간, 나
