이방 사람(인): 43, 49
할례: 44, 48(2)
본토인: 48, 49
4.주제 만들기: 애굽에서 탈출하고 유월절 규례를 받다
5.하나님 찾기 (관찰)
- 이스라엘 백성을 애굽에서 인도하여 나오게 하심
- 유월절 규례에 대해 말씀하심
6.인간 찾기 (관찰)
- 이스라엘 백성이 430년이 끝나는 날, 애굽에서 탈출함
- 이 밤은 여호와의 밤으로 이스라엘 자손이 대대로 지켜야 함
- 모세와 아론이 유월절 규례에 대해 말씀하시는 하나님의 말씀을 들음
- 유월절 제물을 이방 사람은 먹지 못함
- 돈으로 산 종은 할례를 받은 후에 먹을 수 있음
- 거류인과 타국 품꾼은 먹지 못함
- 집에서 먹되 고기를 집 밖으로 내거나 뼈를 꺾어서는 안 됨
- 함께 거류하는 타국인이 여호와의 유월절을 지키고자 하면
- 할례를 받은 후에야 지킬 수 있음
- 온 이스라엘 자손이 하나님께서 명령하신 대로 행함
7.하나님 찾기 (해석) 
- 애굽에서 처음 난 모든 것이 죽은 날 밤, 
- 이스라엘 백성은 안전하게 구원하시고
- 이 구원의 날을 기억하도록 유월절 규례를 주심
- 유월절 제물을 이방 사람은 먹지 못하게 하셨는데,
- 그들이 먹고자 하면 할례를 받고 먹을 수 있게 하셨다.
- 이방인이라도 하나님을 믿겠다 결심한 자는 받아주신 것을 알 수 있다.
- 제물로 쓰인 고기를 조금도 집 밖으로 내지 말고 
- 특별히 뼈도 꺾지 말게 하셨는데,
- 이것은 유월절 제물을 위한 특별한 말씀이었다. 
- 이 제물은 훗날 십자가에 달리실 예수님을 예표 한다.
8.인간(해석)
- 하나님의 놀라운 구원을 경험한 이스라엘 백성은 하나님을 전심으로 경외하게 되었을 것
- 이 세대의 백성은 구원받은 기쁨이 충만하여 유월절 규례를 듣고 그대로 지켰을 것
- 이 규례를 지켜 대대로 구원해 주신 하나님의 밤을 기억하고자 다짐했을 것
- 구원받은 백성이 여호와의 군대, 그리고 무리라고 표현됨
- 이것은 종족별로 질서 정연하게 줄을 지어 나온 것을 의미한 것으로 보임 
- 이방인 중에 하나님을 믿고자 하는 할례를 받았을 것인데, 
- 이것은 이스라엘 시민권을 의미한다.
- 할례를 받은 이방인은 신분이 바뀌었다.
- 예수님을 믿고 구원받은 우리도 하나님 나라의 시민이요, 하나님의 양자된 자녀이다.
9.적용(나)
- 하나님은 우리를 구원하시고 우리에게 큰 기쁨을 주셨다
- 그리고 이것을 기억하기를 원하신다
- 예수님의 십자가와 부활을 기억하되, 
- 특별히 부활절 주간에는 예수님을 더욱 깊이 묵상하며 기뻐해야 한다. 
