2025년 2월02일 출애굽기 14장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
바로의 마음을 완악하게 한즉:4절 8절
여호와께서: 1절 8절
따르리니/따르니: 4절 8절
군대/병거: 4절 6절 7절 9절(2)

4.주제만들기: 
이스라엘 백성을 추격하는 애굽 군사들

5.하나님 찾기 (관찰)
모세에게 말씀하시는 여호와.
바로의 마음을 완악하게 허락하신 여호와.

6.인간 찾기(관찰)
여호와의 명령대로 이스라엘 백성을 이끄는 모세.
이스라엘 백성을 쫓아가는 애굽 군인들.
그 모습을 보고 두려워하는 이스라엘 백성.

7.하나님 찾기(해석)
 각기 다른 세 가지 종류의 마음을 발견한다. 먼저 하나님 마음은 스스로의 영광을 준비하고 계시며 그 곳에 자녀들이 함께 참여하기를 원하고 계신다. 

하나님은 특별히 극적인 연출 즉 애굽 왕과 그의 신하들의 마음이 변하도록 허락하셨다. 

그들로  하여금 이스라엘 백성들을 쫓아 결국 크게 실패하여 크신 하나님을 경험케 하는 마음이셨다. 
그것으로 살아계신 하나님이 참 왕이신 것을 깨닫게 하신다.


8.인간 찾기 (해석)
두 번째는 애굽 왕 바로의 마음이다. 10가지 재앙을 경험하고도 놓지 못하는 욕망과 단단한 분노의 마음으로 완전 자신을 패망으로 이끈다. 

자신이 큰 권세와 열정이 있더라도 주님이 원하지 않는 길이라면 절제와 멈출 수 있는 용기기 필요하다.

셋째로는 이스라엘 백성의 마음이다. 수많은 기적을 통하여 이제는 노예의 신분에서 자유인으로 이끄시는 하나님의 손길을 경험했음에도 뒤쫓는 애굽 군사들을 보고 심할 정도로 두려워하는 마음이다. 

아마 그들이 크게 겁을 내는 이유는 큰 두려움이 그들의 눈을 가리어 현재도 역사하실 수 있는 하나님의 권능을 놓치고 있다는 것 같다. 

그러므로  도우실 수 있는 하나님을 순간마다 느끼고 의지하는 것이 매우 중요하다 생각이 된다.

9.적용(나):
현존하시고 지금 함께하시는 여호와 하나님을 더욱 신뢰하며  의지하는 삶을 살아야겠다.

10. 영적터치 (단어 또는 구절)
사람들이 나를 여호와인 줄 알게하리라.

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-03', '출애굽기', '14장 11절~20절', '하나님의 구원과 전능하신 능력을 신뢰하라', '[출14:11-20]
11 그들이 또 모세에게 이르되 애굽에 매장지가 없어서 당신이 우리를 이끌어 내어 이 광야에서 죽게 하느냐 어찌하여 당신이 우리를 애굽에서 이끌어 내어 우리에게 이같이 하느냐
12 우리가 애굽에서 당신에게 이른 말이 이것이 아니냐 이르기를 우리를 내버려 두라 우리가 애굽 사람을 섬길 것이라 하지 아니하더냐 애굽 사람을 섬기는 것이 광야에서 죽는 것보다 낫겠노라
13 모세가 백성에게 이르되 너희는 두려워하지 말고 가만히 서서 여호와께서 오늘 너희를 위하여 행하시는 구원을 보라 너희가 오늘 본 애굽 사람을 영원히 다시 보지 아니하리라
14 여호와께서 너희를 위하여 싸우시리니 너희는 가만히 있을지니라
15 여호와께서 모세에게 이르시되 너는 어찌하여 내게 부르짖느냐 이스라엘 자손에게 명령하여 앞으로 나아가게 하고
16 지팡이를 들고 손을 바다 위로 내밀어 그것이 갈라지게 하라 이스라엘 자손이 바다 가운데서 마른 땅으로 행하리라
17 내가 애굽 사람들의 마음을 완악하게 할 것인즉 그들이 그 뒤를 따라 들어갈 것이라 내가 바로와 그의 모든 군대와 그의 병거와 마병으로 말미암아 영광을 얻으리니
18 내가 바로와 그의 병거와 마병으로 말미암아 영광을 얻을 때에야 애굽 사람들이 나를 여호와인 줄 알리라 하시더니
19 이스라엘 진 앞에 가던 하나님의 사자가 그들의 뒤로 옮겨 가매 구름 기둥도 앞에서 그 뒤로 옮겨
20 애굽 진과 이스라엘 진 사이에 이르러 서니 저쪽에는 구름과 흑암이 있고 이쪽에는 밤이 밝으므로 밤새도록 저쪽이 이쪽에 가까이 못하였더라

