4.주제 만들기: 바다 가운데를 육지처럼 건너는 이스라엘 자손

5.하나님 찾기 (관찰)
- 바다에 동풍을 일으키시고,
- 바다가 마른 땅이 되게 하심
- 이스라엘 백성을 구원하시되,
- 바로와 애굽 군대는 전멸시키시는 하나님 

6.인간 찾기 (관찰)
- 모세가 바다 위로 손을 내밈
- 이스라엘 자손이 물이 갈라져 마른 땅이 된 바다 가운데를 걸어감
- 바로의 군대가 이스라엘 자손을 추격하여 바다 가운데로 들어감
- 바로의 군대가 달리기가 어렵게 됨
- 여호와가 이스라엘을 위하여 싸움을 알고 도망하자고 외침
- 모세가 손을 바다 위로 손을 내밀어 
- 애굽 군대 위에 물이 다시 흐르게 함
- 애굽 군대가 전멸됨
- 이스라엘 백성이 바닷가에 죽어 있는 애굽 군대를 봄
- 이스라엘이 여호와의 그 큰 능력을 보았으므로
- 여호와를 경외하며 여호와와 그의 종 모세를 믿었음

7.하나님 찾기 (해석) 
- 애굽 모든 사람과 이스라엘 자손에게 
- 하나님의 영광을 나타내시고, 
- 하나님이 모든 사람의 하나님, 곧 주 되심을 알리심
- 하나님은 말씀으로 바다를 마르게 할 수 있지만,
- 모세의 손 내미는 동작과 동풍을 사용하여 
- 바다를 갈라지게 하고 마른 땅이 되게 하심
- 이를 통해 인간의 순종과 
- 더불어 자연이라는 재료의 중요성에 대해 생각할 수 있음
  
8.인간(해석)
- 모세가 어떤 군더더기 없이 하나님의 말씀대로 행함
- 성령에 감동되어 자신의 자유의지를, 전심을 하나님께 내어드린 것
- 강하게 불어오는 동풍을 맞으면서,
- 마른 땅, 아마도 너비가 수백 미터 또는 수천 미터가 될 마른 땅을 건너면서(수백만 명이 건너기 위해서는 굉장히 넓은 길이 필요함),
- 좌우로 높은 벽이 된 바닷물을 보면서 하나님의 위대하심을 체험한 것.
- 애굽 군대는 갈라져 마른 땅이 된 바다를 건너면서 
- 하나님의 위대하심을 느꼈을지, 
- 바다 가운데에서 병거의 바퀴가 움직이지 않을 때 느꼈을지,
- 또는 바다가 그들을 덮치고 나서야 비로소 느꼈을지는 알 수 없음
- 다만, 그들도 하나님이 사람의 생명을 주관하심을, 자신의 생명도 주관하심을 깨달았을 것
- 바닷가에 올라온 이스라엘 백성은 애굽 군대가 바닷물에 잠기는 엄청난 장면(바닷물이 잔잔하게 덥치지는 않았을 것을 상상해 볼 수 있다. 그것은 충격만으로 사람을 기절시키는 엄청나게 큰 파도였을 것)을 목격했을 것이고
- 바닷가에 죽어 있는 애굽 군대를 눈으로 보았다
- 자신을 살리신 하나님의 구원을 눈으로 목격한 이스라엘은,
- 여호와 하나님을 경외할 수밖에 없었다.
- 신약에서 예수님의 부활을 체험하고,
- 말씀하신 대로 살아나신 예수님의 부활체를 보고 나서야,
- 비로소 예수님을 하나님으로 믿게 된 제자들과 관련이 있다.

9.적용(나)
- 하나님을 체험해야만 믿음이 생길 수 있다.
- 이 체험은 내가 찾아가는 것이 아니라, 하나님이 찾아와서 주신다.
- 구원은 받는 것이지, 스스로 얻어내는 것이 아님을 알 수 있다.
- 찾아오셔서 감동을 주시고, 구원해 주신 하나님께 감사하며,
- 오늘도 내게 주어진 길을 묵묵히 걸어가야겠다.

10. 영적터치(단어/구절)  
  31   이스라엘이 여호와께서 애굽 사람들에게 행하신 그 큰 능력을 보았으므로 백성이 여호와를 경외하며 여호와와 그의 종 모세를 믿었더라
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-05', '출애굽기', '15장 1절~10절', '', '(출애굽기 15장)
1.  이 때에 모세와 이스라엘 자손이 이 노래로 여호와께 노래하니 일렀으되 내가 여호와를 찬송하리니 그는 높고 영화로우심이요 말과 그 탄 자를 바다에 던지셨음이로다
2. 여호와는 나의 힘이요 노래시며 나의 구원이시로다 그는 나의 하나님이시니 내가 그를 찬송할 것이요 내 아버지의 하나님이시니 내가 그를 높이리로다
3. 여호와는 용사시니 여호와는 그의 이름이시로다
4. 그가 바로의 병거와 그의 군대를 바다에 던지시니 최고의 지휘관들이 홍해에 잠겼고
5. 깊은 물이 그들을 덮으니 그들이 돌처럼 깊음 속에 가라앉았도다
6. 여호와여 주의 오른손이 권능으로 영광을 나타내시니이다 여호와여 주의 오른손이 원수를 부수시니이다
7. 주께서 주의 큰 위엄으로 주를 거스르는 자를 엎으시니이다 주께서 진노를 발하시니 그 진노가 그들을 지푸라기 같이 사르니이다
8. 주의 콧김에 물이 쌓이되 파도가 언덕 같이 일어서고 큰 물이 바다 가운데 엉기니이다
9. 원수가 말하기를 내가 뒤쫓아 따라잡아 탈취물을 나누리라, 내가 그들로 말미암아 내 욕망을 채우리라, 내가 내 칼을 빼리니 내 손이 그들을 멸하리라 하였으나
10. 주께서 바람을 일으키시매 바다가 그들을 덮으니 그들이 거센 물에 납 같이 잠겼나이다

