4.주제만들기: 
모세의 노래

5.하나님 찾기 (관찰)
힘이 되신 여호와.
용사되신 여호와.
원수를 부수시는 여호와.
바람을 일으시키시는 주님.

6.인간 찾기(관찰)
승리의 여호와를 찬양하는 모세와 이스라엘 자손들.

7.하나님 찾기(해석)
 
8.인간 찾기 (해석)
이 순간만큼은 이스라엘 백성들이 여호와 하나님을 경배하고 찬양하는 모습이다. 

수백 년 동안 자신과 가족 그리고 동족들을 괴롭히고 노예 삼았던 애굽의 군대가 힘없이 홍해에 수장되는 모습을 보니 더욱 그랬을 것이다. 

세상에서 평생 괴롭히는 요소들이 사람마다 다를 것이다. 어떤 사람은 건강 문제 다른 사람은 인간관계를 통하여 받은 상처 아니면 사랑하는 사람과 뜻하지 않는 상처들이 애굽 군사들처럼 있을 것이다. 

하지만 때가 되면 온전히 그것으로부터 해방되어 온전히 주를 찬양하는 날이 속히 올 것이다. 우리를 괴롭히는 요소가 아무리 강해 보여도 8절의 말씀처럼 "주의 콧김에 물이 쌓이되 파도가 언덕같이 일어나고" 주님이 도와주시면 모든 문제가 쉽게 해결될 것이다. 

모든 일들을 주님께 맡기고 오직 찬양하는 것이 복된 삶인 것 같다.

9.적용(나):
승리의 하나님을 믿고 인내하며 늘 삶가운데 찬양하는 삶을 살아야겠다.

10. 영적터치 (단어 또는 구절)
2절: 여호와는 나의 힘이요 노래시며 나의 구원이시로다 그는 나의 하나님이시니.

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

