INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-07', '출애굽기', '15장 21절~27절', '인간을 향한 하나님의 두 번째 테스트', '[출15:21-27]
21 미리암이 그들에게 화답하여 이르되 너희는 여호와를 찬송하라 그는 높고 영화로우심이요 말과 그 탄 자를 바다에 던지셨음이로다 하였더라
22 모세가 홍해에서 이스라엘을 인도하매 그들이 나와서 수르 광야로 들어가서 거기서 사흘길을 걸었으나 물을 얻지 못하고
23 마라에 이르렀더니 그 곳 물이 써서 마시지 못하겠으므로 그 이름을 마라라 하였더라
24 백성이 모세에게 원망하여 이르되 우리가 무엇을 마실까 하매
25 모세가 여호와께 부르짖었더니 여호와께서 그에게 한 나무를 가리키시니 그가 물에 던지니 물이 달게 되었더라 거기서 여호와께서 그들을 위하여 법도와 율례를 정하시고 그들을 시험하실새
26 이르시되 너희가 너희 하나님 나 여호와의 말을 들어 순종하고 내가 보기에 의를 행하며 내 계명에 귀를 기울이며 내 모든 규례를 지키면 내가 애굽 사람에게 내린 모든 질병 중 하나도 너희에게 내리지 아니하리니 나는 너희를 치료하는 여호와임이라
27 그들이 엘림에 이르니 거기에 물 샘 열둘과 종려나무 일흔 그루가 있는지라 거기서 그들이 그 물 곁에 장막을 치니라

