- 백성(24,25,26,27절)
- 물(22,25절)
4. 주제만들기: 인간을 향한 하나님의 두 번째 테스트
5. 하나님 찾기 (관찰)
- 한 나무를 가리켜 물에 던지게 하여 물을 달게 하심
- 이스라엘 백성을 위해 법도와 율례를 정하여 백성들을 시험하심
6. 인간 찾기 (관찰)
- 찬양하는 미리암
- 이스라엘 백성을 인도하는 모세
- 사흘 동안 물을 얻지 못하자 모세를 원망하는 백성들
- 여호와께 부르짖는 모세
7. 하나님 찾기 (해석) 
- 인간을 향한 하나님의 첫 번째 테스트는 아담과 하와였고, 이스라엘 백성들을 대상으로 두 번째 시험을 계획하신다. 하나님의 첫 번째 테스트는 완벽한 천국을 만드시고, 모든 권한을 다 주신 후에 진행한 테스트라면 두 번째 테스트는 인간에게 자신의 능력을 아낌없이 보여주시고, 이스라엘 백성을 위한 법도와 율례를 친히 만들어 그것을 지키도록 시험하셨다. 
8. 인간(해석):
- 이스라엘 백성들은 하나님을 찬양한지 불과 사흘만에 육체적인 한계에 이르자 모세를 원망을 하게 된다. 육체적인 한계에 다르지 않았기 때문에 어떻게 하나님을 사흘만에 잊느냐라고 하지만 우리가 금식을 3일만 하더라도 몸이 힘든 것을 느끼듯이 광야에서 사흘길을 아무것도 먹지 못한 백성의 심정은 충분히 이해간다.
- 고난 가운데 두 부류의 모습이 나타날 것이다. 하나님께 부르짖는 사람과 상황을 원망하는 사람이다. 누구나 당연히 나는 하나님께 부르짖을거야라고 생각을 하지만 현실은 이스라엘 백성처럼 원망하는 사람이 더 많다는 것이다. 
- 하나님은 왜 이스라엘 백성을 시험하셨을까? 여러 가지 이유가 있겠지만 이스라엘 백성을 하나님께 종속 시키고, 순종과 말씀을 의지하는 법을 배우게하려 하셨을 것이다. 이스라엘 백성을 훈련과 시험으로 믿음의 사람이 되도록 하신 것이다.
- 이 과정을 거쳐야 우리는 원망하는 존재에서 하나님께 부르짖는 존재가 된다. 고난은 결국 우리에게 유익이 될 것이다.
9. 적용(나): 
- 자유를 허락하셨고, 거룩함과 능력을 보여주셨음에도 하나님을 제대로 따르지 못함을 회개하고, 삶의 모든 것은 주님으로부터 시작되도록 훈련이 되어야겠다.
- 성경 읽는 것에 더욱 힘써야겠다.
10. 영적터치(단어/구절)
- 시험
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-08', '출애굽기', '16장 1절~10절', '', '(출애굽기 16장)
1.  이스라엘 자손의 온 회중이 엘림에서 떠나 엘림과 시내 산 사이에 있는 신 광야에 이르니 애굽에서 나온 후 둘째 달 십오일이라
2. 이스라엘 자손 온 회중이 그 광야에서 모세와 아론을 원망하여
3. 이스라엘 자손이 그들에게 이르되 우리가 애굽 땅에서 고기 가마 곁에 앉아 있던 때와 떡을 배불리 먹던 때에 여호와의 손에 죽었더라면 좋았을 것을 너희가 이 광야로 우리를 인도해 내어 이 온 회중이 주려 죽게 하는도다
4. 그 때에 여호와께서 모세에게 이르시되 보라 내가 너희를 위하여 하늘에서 양식을 비 같이 내리리니 백성이 나가서 일용할 것을 날마다 거둘 것이라 이같이 하여 그들이 내 율법을 준행하나 아니하나 내가 시험하리라
5. 여섯째 날에는 그들이 그 거둔 것을 준비할지니 날마다 거두던 것의 갑절이 되리라
6. 모세와 아론이 온 이스라엘 자손에게 이르되 저녁이 되면 너희가 여호와께서 너희를 애굽 땅에서 인도하여 내셨음을 알 것이요
7. 아침에는 너희가 여호와의 영광을 보리니 이는 여호와께서 너희가 자기를 향하여 원망함을 들으셨음이라 우리가 누구이기에 너희가 우리에게 대하여 원망하느냐
8. 모세가 또 이르되 여호와께서 저녁에는 너희에게 고기를 주어 먹이시고 아침에는 떡으로 배불리시리니 이는 여호와께서 자기를 향하여 너희가 원망하는 그 말을 들으셨음이라 우리가 누구냐 너희의 원망은 우리를 향하여 함이 아니요 여호와를 향하여 함이로다
9. 모세가 또 아론에게 이르되 이스라엘 자손의 온 회중에게 말하기를 여호와께 가까이 나아오라 여호와께서 너희의 원망함을 들으셨느니라 하라
10. 아론이 이스라엘 자손의 온 회중에게 말하매 그들이 광야를 바라보니 여호와의 영광이 구름 속에 나타나더라

