4.주제만들기: 
이스라엘 백성의 원망에 자비로 베푸시는 여호와.

5.하나님 찾기 (관찰)
원망하는 이스라엘 백성에게 매일 먹을 고기와 떡을 준비하시는 여호와.
모세와 아론에게 일어날 일들을 말씀하시는 여호와.
장차 영광을 보여주실 여호와.

6.인간 찾기(관찰)
원망하는 이스라엘 백성들(애굽 땅에서 먹었던 음식을 그리워함)
여호와 말씀을 듣는 모세와 아론.

7.하나님 찾기(해석)
 
8.인간 찾기 (해석)
변덕스러운 이스라엘 백성들은 또다시 원망한다. 애굽에서 노예 생활을 하며 먹었던 양식을 그리워한다는 것이었다. 

얼마 전 홍해를 건너면서 하나님을 찬양했던 사람들의 모습인가 하는 의구심이 들 정도이다 

그러한 모습을 보고 계신 하나님은 그들에게 자비를 베푸시고 하늘에서 내리는 비 같은 거룩한 양식을 준비하고 계신다. 

원망과 자비가 묘하게 겹치는 분위기다. 그러면서 평상시 나를 포함한 신자들에게도 쉽게 볼 수 있는 모습이라 여겨진다. 

무엇보다 일관성 있게 인도하시고 사랑을 베푸시는 하나님이 아버님이라 큰 안심을 해본다. 

반면에 한가지 또 깨우치는 것은 내가 스스로 나서서 받은 은혜를 나눈 후에 그 말에 책임지는 것이 얼마나 중요한지 알 것 같다.

9.적용(나):
혹시 답답한 환경에  있더라도 주님을 원망하지 않고 차분히 크신 주님의 일하심에 더욱 경청하는 사람이 되야겠다.

10. 영적터치 (단어 또는 구절)
7절: 아침에는 너희가 여호와의 영광을 보리니 이는 여호와께서 너희가 자기를 향하여 원망함을 들으셨음이라 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-09', '출애굽기', '16장 11절~20절', '', '(출애굽기 16장)
11. 여호와께서 모세에게 말씀하여 이르시되
12. 내가 이스라엘 자손의 원망함을 들었노라 그들에게 말하여 이르기를 너희가 해 질 때에는 고기를 먹고 아침에는 떡으로 배부르리니 내가 여호와 너희의 하나님인 줄 알리라 하라 하시니라
13. 저녁에는 메추라기가 와서 진에 덮이고 아침에는 이슬이 진 주위에 있더니
14. 그 이슬이 마른 후에 광야 지면에 작고 둥글며 서리 같이 가는 것이 있는지라
15. 이스라엘 자손이 보고 그것이 무엇인지 알지 못하여 서로 이르되 이것이 무엇이냐 하니 모세가 그들에게 이르되 이는 여호와께서 너희에게 주어 먹게 하신 양식이라
16. 여호와께서 이같이 명령하시기를 너희 각 사람은 먹을 만큼만 이것을 거둘지니 곧 너희 사람 수효대로 한 사람에 한 오멜씩 거두되 각 사람이 그의 장막에 있는 자들을 위하여 거둘지니라 하셨느니라
17. 이스라엘 자손이 그같이 하였더니 그 거둔 것이 많기도 하고 적기도 하나
18. 오멜로 되어 본즉 많이 거둔 자도 남음이 없고 적게 거둔 자도 부족함이 없이 각 사람은 먹을 만큼만 거두었더라
19. 모세가 그들에게 이르기를 아무든지 아침까지 그것을 남겨두지 말라 하였으나
20. 그들이 모세에게 순종하지 아니하고 더러는 아침까지 두었더니 벌레가 생기고 냄새가 난지라 모세가 그들에게 노하니라

