4. 주제만들기: 거룩함을 유지해야하는 안식일

5. 하나님 찾기 (관찰)
- 메추라기와 이슬을 주시고, 여섯째날에는 이틀치 양식을 거두라 말씀하심
- 일곱째 날에도 양식을 거두러 나가는 백성을 향해 언제까지 계명과 율법을 지키지 아니하겠느냐 말씀하심
- 일곱째 날에는 처소에서 나오지 말라 명하시는 하나님

6. 인간 찾기 (관찰)
- 이틀치를 거두었으나 냄새도 나지 않고, 벌레도 생기지 않음
- 일곱째 날에 백성 중 어떤 사람들은 곡식을 거두러 나감

7. 하나님 찾기 (해석)
- 일곱째 날 안식을 위해 여섯째 날에 양식을 미리 거두게 하심은 하나님께 온전히 집중하는 시간을 갖게 하셨다. 하나님은 우리가 어떠한 상황 가운데에도 그분을 신뢰하고 의지하고 하나님과 함께하는 시간을 원하신다.

8. 인간(해석):
- 훈련 가운데 있는 이스라엘 백성은 메추라기와 만나(이슬)을 거둘 수 있게 되자 자신의 분량보다 더 거두거나, 분량보다 더 먹고자 안식일에 양식을 찾았다.
- 언제 메추라기와 만나가 끊길지 모른다는 두려움으로 양식을 더 쌓아두고자 했을 것이고, 더 먹고 싶었을 수도 있다.
- 하나님께선 원하신건 그분께 집중하는 것이다. 현재의 고된 삶, 예측할 수 없는 미래, 풍요로움 가운데 생기는 욕심에서 벗어나 오로지 하나님을 의지하기 원하신다. 
- 그리고 규례와 율법으로 집중해야할 우선순위를 알려주신 것이다. 내가 무엇을 더하려거나 덜하지 말고 그것만 하면 된다. NKFC와 NK MISSIOM FOR YOU도 마찬가지이다. 내가 무엇을 더하거나 덜하려고 하지 말고 하나님께서 원하시는 것에만 집중하면 된다. 

9. 적용(나): 
- 사역에 대한 두려움, 답답함 등 모두 내려놓고 하나님께 집중해야겠다.
- 지금까지 나의 삶을 인도하신 하나님께 감사드리며 하나님의 계획을 쫓아 살아가야겠다.

10. 영적터치(단어/구절)
- 어느 때까지 너희가

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

