7.하나님 찾기(해석)

8. 인간 찾기(해석)
모세의 겸손함을 배울 수 있다. 이드로가 아무리 모세의 장인 이긴 하나 모세가 이스라엘 전체 백성을 이끄는 리더이기에 이드로의 조언을 받아들이지 않을 수 있었다. 

더군다나 장인 이드로는 상당한 노년이라 짐작할 때 그러한 핑계로 쉽게 넘어갈 수도 있었다. 하지만 모세는 좋은 충고를 경청하고 받아들였다. 

능력이 있는 자란 하나님을 두려워하며 진실하고 이익을 미워한다고 장인 이드로가 말했다. 이것은 이드로가 정한 능력 있는 자의 표본임에도 놀라운 믿음이라 볼 수 있다. 

더군다나 천부장이나 백부장, 오십부장,십부장 처럼 중요한 자리를 세우는 일은 공동체의 성공과 실패의 존망이 있으므로 선출 기준이 중요하다.을 중요한 일이므로 선출능력의 기준이 중요함을 느낀다. 나도 혹시 사람을 대할때 세상의 스팩을 따르지 않도록 경계 하여야겠다.

9.적용(나):
믿음의 선배들의 말에 더욱 경청하는 자세를 가져야겠다. 영적 교재도 더욱 읽어야겠다.

