5. 하나님 찾기 (관찰)
- 산에서 모세를 불러 이스라엘 백성들에게 명령하시는 하나님

6. 인간 찾기 (관찰)
- 하나님을 말씀을 듣고 백성들에게 전하는 모세
- 모세의 말을 들은 이스라엘 백성은 하나님께서 명하신 대로 행하겠다고 약속함

7. 하나님 찾기 (해석) 
- 하나님께선 애굽을 탈출하고 3개월이 지난 후에야 이스라엘 백성들에게 명령하셨다. 이스라엘 백성은 하나님의 보호하심 아래 전적으로 안정적인 생활을 이어가고 있다. 그러나 시내 광야에 이르자 하나님은 모세를 통해 명령하셨다. 
- 우리의 신앙생활 중 이러한 일들이 유사하게 발생하기도 한다. 기도가 응답되고, 필요를 채워주시는 하나님을 경험할 때 우리는 안정적인 신앙생활을 이어간다. 그러나 광야로 들어가게 될 때 우리는 어떻게 될까? 하나님을 온전히 믿으며 신앙생활을 이어갈 수 있을까? 
- 하나님은 우리를 광야에서 훈련시키기 원하신다. 그것은 우리의 신앙과 성장에 유익한 일이기 때문이다. 하나님은 이스라엘 백성에게 제사장 나라가 되며 거룩한 백성이 되게 해주겠다고 언약하셨다. 

8. 인간(해석):
- 이스라엘 백성은 모세의 말에 기꺼이 명령을 지키겠다고 약속하며 순종하는 모습을 보인다. 이스라엘 백성은 광야에서의 삶이 어떠할지 예측하지 못했을 것이다. 우리의 신앙생활도 마찬가지이다. 좋은 일이 있을 때는 하나님을 찬양하지만 고난 가운데에선 하나님을 찾기 어렵다. 그렇기 때문에 광야에서의 훈련은 우리에게 매우 유익한 일이다. 단, 그것을 이겨내었을 경우에 말이다. 

9. 적용(나): 
- 광야의 훈련을 이겨내는 것은 나의 능력으로 불가능하다. 전적으로 하나님을 의지하고 그 분의 계획을 신뢰해야겠다.
- 교만하지 않고 겸손함으로 하나님의 말씀을 보고 들어야겠다.

10. 영적터치(단어/구절)
- 그들이 시내 광야에 이르니라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

