- 모세를 부르시는 하나님

6.인간 찾기(관찰)
- 하나님의 명령을 듣는 모세
- 하나님의 말씀대로 백성들을 성결하게 하고
- 하나님의 명령을 백성에게 전하는 모세
- 하나님께서 강림하실 때 일어나는 현상을 보고 두려워하는 백성
- 모세가 하나님께 말함
- 하나님의 말씀대로 시내산 꼭대기로 올라가는 모세

7.하나님 찾기(해석)
- 백성에게 나타나시되,
- 백성은 경계를 넘지 못하게 하심
- 그러나 모세는 올라오게 하시므로
- 이 사건을 통해 하나님이 모세를 얼마나 가까이 하시는지,
- 모세가 얼마나 특별한 존재인지를 백성들이 깨닫게 하심
- 이스라엘 백성이 모세를 강력한 지도자로 인정할 수 밖에 없도록,
- 하나님께서 특별히 택한 지도자인 것을 각인시키시기 위함

8.인간 찾기(해석)
- 모세는 자신을 위해 백성들 앞에 강림해 주시는 하나님을 보며, 
- 엄청난 감동과 전율을 느꼈을 것이다.
- 하나님의 강림을 보며 두려워하는 백성은,
- 자신들에게 주어진 경계와는 달리,
- 하나님께서 부르신 곳, 즉 하나님 바로 앞으로 나아가는 모세를 바라보며,
- 모세가 하나님께 특별히 택함 받은 자임을 깨달았을 것이다.

9.적용(나) 
- 하나님의 손에 붙들려 사역하시는 분들을 보면,
- 확실히 뭔가가 다르다.
- 그런 분을 존경하고 순종할 줄 아는 믿음의 사람이 돼야겠다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

