4.주제 만들기: 
구분하시는 여호와.

5.하나님 찾기 (관찰)
백성에게 시내산에 오르지 못하도록 모세를 통하여 명령하시는 여호와.
제사장들과 백성에게 경계를 넘지 못하도록 명령하시는 여호와.
거룩하고 성결하도록 명령하시는 여호와.


6.인간 찾기(관찰)
여호와의 명령을 받고 백성에게 알리는  모세.

7.하나님 찾기(해석)
하나님은 인간들이 스스로 높아지지 못하도록 경계를 확실히 정하신 것 같다. 

이스라엘 백성들이 예고 없이 하나님께 밀고 올라오거나 정해놓은 경계를 제사장들 포함하여 넘지 못하도록 하였다. 철저한 구별하시는 하나님의 성품을 볼 수 있다.

또한 거룩하신 하나님을 알 수 있다. 제사장들에게 몸을 성결하도록 명령하셨다. 

마음의 성결함뿐만 아니라 몸도 포함한 것을 보면 하나님은 제사장의 바른 품의도 중요시 보시는 것 같다.

구약에서 특별한 대제사장 역할을 하는 모세 외에는 하나님께 직접 대면하는 것을 허용하지 않으신 것 같다. 

그러나 이후에는 예수님 사랑의 십자가 공로로 새로운 법도인 ''만인 제사장''으로 개인적으로 누구든지 하나님 자녀면 하나님께로 직접 나갈 수 있는 은혜를 부여받았다.

8. 인간 찾기(해석)

9.적용(나):
주님안에서 늘 겸손한 종이 되도록 더욱 노력해야겠다.

