안식일: 8, 10

4.주제 만들기: 십계명을 주시는 하나님

5.하나님 찾기(관찰)
- 시내산 꼭대기에서 모세와 아론에게 
- 나는 너를 애굽에서 인도하여 낸 네 하나님 여호와라 말씀하시고, 
- 십계명을 말씀하심

6.인간 찾기(관찰)
- 모세와 아론이 하나님의 말씀을 들음

7.하나님 찾기(해석)
- 특별히 택하시고 지도자로 세운 모세와 아론에게
- 내가 여호와 하나님이라 말씀하심
- 애굽에서 구원하신 것을 말씀하심으로 
- 첫째 모세와 아론이 하나님의 살아계심과 그의 역사를 기억하게 하시며
- 둘째 자신이 두 사람 앞에 임재하였음을 확실히 알려주심

- 십계명을 주시며
- 자신만을 신으로 믿고 다른 신은 두지 말라 하심
- 인간은 자신이 원하는 것을 찾기에, 자기 외에 다른 신을 찾는 존재라는 것을 잘 알고 계심

- 우상을 만들지 말라고 하심
- 인간은 가시적인 존재인데, 
- 하나님은 우리 눈에 보이지 않기 때문에
- 인간이 굳게 믿지 못하고, 눈에 보이는 우상을 만들어 음란하게 섬길 것을 알고 계심

- 자신의 이름을 망령되이 부르지 말라고 하심
- 하나님은 인간에게 경외함을 받을 분인데, 
- 인간들이 자신의 눈에 하나님이 안 보임으로 하나님이 어디 있느냐, 조롱할 것을 알고 계심

- 일곱째 날은 하나님의 안식일이니 아무 일도 하지 말라 명하심
- 하나님은 안식일에 인간도 휴식함과 동시에 하나님을 더 생각하고 예배하며 기념하길 원하심

- 하나님은 인간의 모든 것을 아시지만, 
- 인간이 하나님만을 유일신으로 경외하여 
- 거룩하게 살아가길 원하심. (인간의 본성을 거슬러 세상과 구별된 삶, 즉 십계명을 지키는 삶을 살기를 원하심)
 
8.인간 찾기(해석)
- 우레와 번개와 나팔소리와 연기 가운데 임재하신 하나님을 경외하며
- 두렵고 떨리는 마음으로 말씀을 듣고 있을 것이다.

9.적용(나) 
- 십계명을 지키는 것은 결코 쉽지 않다. 내 의지로 할 수 있는 것이 아니다.
- 하나님을 경외하며, 성령님을 의지하여 십계명을 잘 지키며 살아야겠다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
