2025년 2월22일 출애굽기 20장21절~26절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
제단/토단: 24절 25절 26절
말고/말라: 23절 25절 26절
모세: 21절 22절 25절 26절
여호와/하나님: 21절 22절 24절 25절

4.주제 만들기: 
제단에 대한 가르침

5.하나님 찾기 (관찰)
모세에게 제단(번제와 화목제)에 대하여 지침을 주시는 여호와.
신상(우상)을 만들지 말것을 명령하시는 여호와.
하나님 이름을 기념하는 곳에 복을 주시겠다고 말씀하시는 여호와.

6.인간 찾기(관찰)
제단에 관하여 가르치시는 여호와로부터 경청하는 모세.

7.하나님 찾기(해석)
주의 이름을 기념하는 곳 어디든지 하나님은 임하셔서 복을 주신다고 하셨다. 

즉 무소 부재하시고 전능하신 하나님은 우리와 함께하심을 약속하신 것이다. 

특별히 번제와 화목제 즉 예배를 통하여 임하시기를 기뻐하심을 알 수 있고 개인기도 할 때 주의 이름을 찾는 자들에게 응답의 복을 주심을 알 수 있다. 

즉 어느 곳에 있든지 복을 주신다. 그렇게 생각하면 세계 복음화와 연관이 있는 것으로 확장됨을 생각하게 된다. 

세게 곳곳에 아직도 참 신 이신 하나님의 이름을 높이지 않고 그들만의 가짜 복을 위하여 우상을 추종하는 사람들이 얼마나 많은가? 

그런 면에서 먼저 그 진리를 믿음으로써 받은 복을 그들에게도 나누어 주시기를 주님은 간절히 원하심이 확실하다. 예수님의 십자가 사랑으로 이미 증명되었음을 알 수 있다. 

그것이 바로 여호와 하나님의 본심인 것도 쉽게 알 수 있다.
주님의 이름이 그곳 가운데 기념되고 높여지는 것을 주님은 바라고 계심이 확신한다.

8. 인간 찾기(해석)

9.적용(나):
주님의 이름을 더욱 찬양 할 뿐만 아니라 알리는 종이 되야겠다. 그렇게 하기위하여 더욱 국내 대교 복음 전도에 힘쓰고 세계 복음화에도 우리 남북청년연합 선교회가 적극 참여하도록 헌신해야겠다.

10. 영적터치 (단어 또는 구절)
24절: 내 이름을 기념하게 하는 모든 곳에서 네게 임하여 복을 주리라.

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-23', '출애굽기', '21장 1절~10절', '', '(출애굽기 21장)
1.  네가 백성 앞에 세울 법규는 이러하니라
2. 네가 히브리 종을 사면 그는 여섯 해 동안 섬길 것이요 일곱째 해에는 몸값을 물지 않고 나가 자유인이 될 것이며
3. 만일 그가 단신으로 왔으면 단신으로 나갈 것이요 장가 들었으면 그의 아내도 그와 함께 나가려니와
4. 만일 상전이 그에게 아내를 주어 그의 아내가 아들이나 딸을 낳았으면 그의 아내와 그의 자식들은 상전에게 속할 것이요 그는 단신으로 나갈 것이로되
5. 만일 종이 분명히 말하기를 내가 상전과 내 처자를 사랑하니 나가서 자유인이 되지 않겠노라 하면
6. 상전이 그를 데리고 재판장에게로 갈 것이요 또 그를 문이나 문설주 앞으로 데리고 가서 그것에다가 송곳으로 그의 귀를 뚫을 것이라 그는 종신토록 그 상전을 섬기리라
7. 사람이 자기의 딸을 여종으로 팔았으면 그는 남종 같이 나오지 못할지며
8. 만일 상전이 그를 기뻐하지 아니하여 상관하지 아니하면 그를 속량하게 할 것이나 상전이 그 여자를 속인 것이 되었으니 외국인에게는 팔지 못할 것이요
9. 만일 그를 자기 아들에게 주기로 하였으면 그를 딸 같이 대우할 것이요
10. 만일 상전이 다른 여자에게 장가 들지라도 그 여자의 음식과 의복과 동침하는 것은 끊지 말 것이요

