4.주제 만들기: 
종에 관한 법규

5.하나님 찾기 (관찰)
모세에게 법규(일반 종과 여종에 대한것)를 가르치시는 여호와.

6.인간 찾기(관찰)
법규를 경청하는 모세.

7.하나님 찾기(해석)
종에 대한 세우신 법규를 통하여 하나님의 자비로우신 성품을 쉽게 느낄 수 있다. 

먼저 2절에 보면 ''일곱째 해에는 몸값을 물지 않고 나가 자유인이 될 것이며'' 되어 있다. 하나님은 인간들이 기본적으로 세상에서 누릴 수 있는 인간의 기본권을 허용하고 계심을 알 수 있다. 설령 신분이 종이라고 하더라도 기간을 두고 자유인 이로써 보장받기를 원하시는 것 같다. 

마치 수백 년 동안 애굽 땅에서 노예 생활을 했던 이스라엘 백성들을 구출하시고 자유를 공급하신 하나님의 방법과 매우 흡사하다. 

특별히 하나님은 종 중에서도 제일 약체라 생각되는 여종에 관하여 더욱 보살피시는 것 같다. 

9절에 ''그를 딸 같이 대우할 것이요'' 기록된 것을 보면 여 종의 신분 처우에 대한 깊은 평등이 담겨있다. 

이 부분을 두고 생각되는 것은 죄의 노예였던 우리를 십자가의 사랑으로 용서하시고 이제는 주님의 자녀로 신분을 왕족의 자리로 옮겨 놓으신 것처럼 하나님 사랑의 마음을 더욱 느끼게 된다.
 
8. 인간 찾기(해석)

9.적용(나):
하나님이 약자에 대한 배려와 보호하심처럼 나도 주변에 약한자들을 살피고 주님의 사랑을 나누기를 힘써야겠다.

10. 영적터치 (단어 또는 구절)
