18 사람이 서로 싸우다가 하나가 돌이나 주먹으로 그의 상대방을 쳤으나 그가 죽지 않고 자리에 누웠다가
19 지팡이를 짚고 일어나 걸으면 그를 친 자가 형벌은 면하되 그간의 손해를 배상하고 그가 완치되게 할 것이니라
