4. 주제만들기: 살인에 대한 율법

5. 하나님 찾기 (관찰)
- 살인에 관한 율법을 알려주심

6. 인간 찾기 (관찰)

7. 하나님 찾기 (해석) 
- 하나님은 이스라엘이 거룩한 백성으로 성장하도록 율법을 만들어주신다. 이번 구절은 살인에 대해 언급하고 있다. 현대나 과거나 비슷한 류의 범죄는 이어져 오고 있다.  
- 하나님은 특별히 고의성에 대해 강조하신다. 만약 고의로 살인하지 않았다면 도피성으로 들어가 자신을 보호할 수 있다. 과정이 어떠하든 그 사람의 마음을 보시고 회개할 수 있는 기회를 주시는 것이다.
- 그러나 분노로 인한 고의적인 살인을 용서하지 않으신다. 그것은 인간이 자신의 죄를 다스리지 못했음을 의미한다. 
- 부모에 대해서는 부모를 저주하는 것만으로도 죽을 것이라 하셨는데, 부모를 공경해야 됨을 특별히 강조하셨다.

8. 인간(해석):
- 하나님이 주신 율법을 통해 당시 인간이 얼마나 미개하고 어리석은 죄인이었음을 깨닫는다. 당시의 죄가 현대까지 이어지고 있으니 참으로 안타까운 현실이다. 인간은 분노와 탐욕 등으로 돌이킬 수 없는 죄를 짓게 된다. 죄에 대해 한없이 연약한 존재이다. 

9. 적용(나): 
- 실제 살인을 하지 않았더라도 갖은 죄로 살인을 이미 저지른 죄인이다. 회개하고 죄성을 끊을 수 있는 예수님만 의지하자.
- 종도 보호하고 아끼신 하나님의 사랑을 기억하고, 동일한 사랑을 실천할 수 있는 사람이 되어야겠다.

10. 영적터치(단어/구절)
- 반드시 죽일 것이라
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

