4.주제 만들기: 배상에 관한 법규

5.하나님 찾기(관찰)
- 배상에 관한 법규를 말씀하시는 하나님

6.인간 찾기(관찰)
- 도둑질 한 소는 다섯 마리, 양은 네 마리로 갚아야 한다.
- 밤에 도둑이 들어온 것을 알고, 그 도둑을 죽이면 죄가 없다.
- 그러나 낮에 이런 일이 있으면 살인죄가 된다.
- 가축을 풀어서 풀을 뜯어 먹게 하였는데, 이 가축이 다른 사람의 밭의 농작물을 뜯어 먹으면, 자기 밭이나 포도원의 가장 좋은 소출로 물어줘야 한다.
- 불을 놔서 남의 곡식이나 밭을 태우면 불을 놓은 사람은 그것을 물어줘야 한다.
- 이웃에게 돈이나 물품을 맡겼는데, 도둑이 들어 그것이 사라지면 도둑이 그것을 배상해야 한다.
- 그러나 도둑이 잡히지 않으면, 그 집 주인은 재판관 앞에 나가 이웃의 물건에 손을 댔는지 안 댔는지 판결을 받아야 한다.
- 어떤 분실물을 서로 자기 것이라 주장하는 일이 생기면,
- 양쪽 모두 재판관 앞으로 나가 판결을 받아야 하며,
- 유죄 판결을 받은 사람은 상대에게 갑절로 배상해야 한다.

7.하나님 찾기(해석)
- 화평한 공동체 형성을 위해 법규를 주시는 하나님
- 남의 것을 탐하는 문제에 대한 법규를 주심

8.인간 찾기(해석)
- 비록 도둑이라도 낮에 죽이면 살인죄가 된다는 명령을 볼 때
- 하나님께서 생명을 소중히 여기시는 것을 알 수 있음
- 가축을 먹일 때는 다른 집에 피해를 줄 수 있으므로 직접 가축을 돌봐야 하고,
- 그렇게 하지 못했을 때는 자기 것의 가장 좋은 것으로 책임을 져야 한다.
- 이웃에게 돈이나 물품을 맡기는 일은 없는 것이 좋다.
- 이웃의 돈이나 물품을 맡았을 때 그것에 욕심이 생길 수 있으니 주의해야 한다.
- 분실물은 손대지 않는 것이 좋다.
- 인간에게는 남의 것을 탐하는 본성이 있으니 주의해야 한다.

9.적용(나) 
- 내 속의 탐심에 주의해야 한다.
- 탐심을 내버려 두면, 그 탐심에 사로잡혀 죄를 짓게 된다.
- 오늘도 기도와 말씀으로 무장하여 탐심을 물리치고,
- 내가 속한 공동체가 화평한 공동체가 되도록 노력해야겠다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-28', '출애굽기', '22장 11절~20절', '배상, 혼전순결, 행음, 우상 숭배 금지의 규례', '[출22:11-20]
11 두 사람 사이에 맡은 자가 이웃의 것에 손을 대지 아니하였다고 여호와께 맹세할 것이요 그 임자는 그대로 믿을 것이며 그 사람은 배상하지 아니하려니와
12 만일 자기에게서 도둑 맞았으면 그 임자에게 배상할 것이며
13 만일 찢겼으면 그것을 가져다가 증언할 것이요 그 찢긴 것에 대하여 배상하지 아니할지니라
14 만일 이웃에게 빌려온 것이 그 임자가 함께 있지 아니할 때에 상하거나 죽으면 반드시 배상하려니와
15 그 임자가 그것과 함께 있었으면 배상하지 아니할지니라 만일 세 낸 것이면 세로 족하니라
16 사람이 약혼하지 아니한 처녀를 꾀어 동침하였으면 납폐금을 주고 아내로 삼을 것이요
17 만일 처녀의 아버지가 딸을 그에게 주기를 거절하면 그는 처녀에게 납폐금으로 돈을 낼지니라
18 너는 무당을 살려두지 말라
19 짐승과 행음하는 자는 반드시 죽일지니라
20 여호와 외에 다른 신에게 제사를 드리는 자는 멸할지니라

