5. 하나님 찾기 (관찰)
- 이웃의 소유물에 대한 배상과 혼전 순결, 동물과의 행음, 우상 숭배를 금지하는 규례를 말씀하심

6. 인간 찾기 (관찰)

7. 하나님 찾기 (해석)
- 하나님께서 주신 규례를 통해 우리는 당시 이스라엘 백성의 삶의 모습뿐만 아니라, 인간이 얼마나 죄에 쉽게 노출되는 존재인지 알 수 있다. 하나님을 모르고 살아가는 자들이나, 하나님을 믿고 있음에도 불구하고 죄의 영향에서 자유롭지 못한 인간의 연약함이 이 말씀을 통해 드러난다.
하나님은 이스라엘 백성이 죄에 빠지지 않도록 구체적인 규례를 주셨다. 하지만 인간은 단순히 하나님의 말씀을 지키기만 하면 되는 존재임에도 불구하고, 그 말씀을 온전히 따르지 못한다.
- 또한, 하나님은 연약한 자를 살피시고 보호하시는 분이시다. 예를 들어, 약혼하지 않은 처녀를 꾀어 동침하는 남자로부터 여성을 보호하기 위해 법을 주셨다. 이는 단순히 혼전 순결의 중요성을 강조하는 것이 아니라, 사회적 약자인 여성을 보호하시는 하나님의 사랑과 정의를 보여주는 장면이다.- 이러한 하나님의 성품은 오늘날에도 동일하다. 우리가 죄로 인해 연약할 때에도, 하나님은 우리를 돌보시고 보호하시며, 그분의 말씀을 통해 죄에서 벗어날 길을 마련해 주신다. 인간은 연약하지만, 하나님은 그 연약함을 아시고 우리를 끝까지 사랑하시며 인도하신다. 
 
8. 인간(해석):

9. 적용(나):
- 끝까지 우리를 보호하시고 사랑하시는 하나님의 은혜에 감사하다.
- 지치고 포기하고 싶을 때 하나님을 의지하며 살아갈 수 있다는 것이 얼마나 감사한 일인가? 하나님만 의지하자
 
