출애굽기 22장21절~31절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
말라/말며: 21절 22절 28절 29절 
나그네/과부/고아/가난한 자: 21절(2) 22절 24절 25절 
부르짖으면/분르짖음: 23절
유일한 옷/가릴 옷: 26절 27절

4.주제 만들기: 
약자를 돌보시는 여호와 

5.하나님 찾기 (관찰)
약자(나그네,과부,고아,가난한 자)를 보호하시는 여호와.
거룩한 사람이 되기를 요청하시는 여호와.

6.인간 찾기(관찰)

7.하나님 찾기(해석)
하나님은 약자를 보호하시고 그들의 기도 소리를 들으신다. 약자라 하면 나그네와 과부 고아 등을 말할 수 있다. 
특별히 하나님은 그들이 여호와를 찾고 부르짖는다면 더욱 귀를 기울이시는 것 같다. 
그런 면에서 보면 하나님은 애굽에서 노예 생활을 했던 이스라엘 백성의 간절한 기도 소리를 들으시고 해방해 주신 것처럼 누구든지 간절히 찾는 자들의 기도를 받아주심을 볼 수 있다. 

본문 내용을 보면 이스라엘 백성에게 주의를 주신다. 내용으로는 나그네 와 과부 그리고 고아를 괴롭히지 말라는 말씀이다. 
그 말씀을 거슬러 만약 학대하거나 괴롭히면 심판에 대해 말씀하셨다. 생각해보면 누구든지 스스로 겸비하지 않는다면 예외 없이 애굽의 바로 같은 약자를 괴롭히는 존재가 될 수 있음을 자각하게 된다. 
그런 면에서 늘 주님의 말씀을 묵상하고 기도하는 습관이야말로 자신을 점검하므로 교만하지 않도록 지켜주는 큰 선물임을 깨우친다. 
그러한 주님이 주신 선물을 매일매일 열심히 사용하는 것이 매우 필수적인 요소임을 알게 된다.
 
8. 인간 찾기(해석)

9.적용(나):
내 주변에 약해보이는 지체들을 더욱 잘 섬겨야겠다.

10. 영적터치 (단어 또는 구절)
21절: 너희도 애굽 땅에서 나그네였음이라.

