4.주제 만들기: 
정의롭고 자비하신 하나님 법규.

5.하나님 찾기 (관찰)
공평과 정의 그리고 자비에 대한 법규를 가르치시는 여호와.

6.인간 찾기(관찰)
인간들이 따르고 지켜야 할 법규.

7.하나님 찾기(해석)
하나님은 거짓 증언을 싫어하신다. 특별히 다수의 편에 서서 악행을 삼는 것을 더욱 미워하신다. 
이러한 올바르지 않은 행위는 각자 양심을 통하여 느낄 수 있는 부분인데 쉽게 넘어갈 수 있는 함정이 있음을 하나님은 경고하신다.
원수의 나귀와 소가 위기에 처한 모습을 보고 그냥 지나치지 말고 도와주라고 말씀하신다. 사실 모른 채 지나가도 될법한데 일부러 도와주라고 하신 의도는 무엇일까?

더군다나 나귀와 소의 주인이 원수라고 한다면 더욱 쉽지 않을 것이다. 이러한 상태를 하나님도 아실 텐데.
이성적으로 생각하면 쉽게 이해가 되지 않지만, 영적인 시각으로 보니 실마리가 쉽게 풀렸다. 
우리도 주님을 만나기 전 하나님께 대항하며 미워했던 원수였었다. 
하지만 사랑의 하나님이 원수인 우리에게 선을 베푸사 길 잃은 나귀와 소처럼 주인에게 돌려주시는 그것처럼 우리글 원래의 주인을 만나게 해주셨다.
 짧은 규범을 통해서도 하나님이 얼마나 자비로우시고 위대하신지 쉽게 깨우칠 수 있다. 그러한 참 주인이신 사랑의 하나님을 더욱 찬양합니다!!

