6. 인간 찾기 (관찰)

7. 하나님 찾기 (해석) 
- 하나님은 가난한 자들을 보호하셨다. 하나님은 가난한 자를 긍휼히 여기는 분이시다. 우리도 그분의 사랑을 본받아 도움이 필요한 곳에 하나님의 긍휼하심을 전할 필요가 있다.
- 하나님은 우리의 쉼을 중요히 여기셨다. 쉼을 통해 우리를 돌봐주신 하나님을 바라볼 수 있는 시간을 주신 것이다. 인간은 욕심이 많고, 하나님을 쉽게 잊는 존재로 하나님을 벗어나지 않도록 집중하는 시간을 마련해주셨다. 당시의 쉼은 종과 가축들이 함께 쉴 수 있는 시간을 주었는데, 낮은 자를 보호하신 하나님의 사랑을 느낄 수 있다.
- 하나님은 다른 신의 이름을 부르지 못하게 하셨으며, 유혹에 쉽게 빠지는 인간을 보호하고자 하셨다. 
- 세 번의 절기를 지키라 명하시며 우리를 구원하신 하나님, 우리를 지키신 하나님, 우리와 함께하시는 하나님을 잊지 않게 하셨다. 하나님을 우리가 찾는 것이 아니라 하나님께서 우리를 찾으시고 보호하심을 느낀다.

8. 인간(해석):

9. 적용(나): 
- 도움이 필요한 곳에 도울 수 있는 용기와 물질을 허락해주시길 기도해야겠다.
- 우리를 보호하시는 하나님의 은혜에 감사드린다.
- 가장 좋을 것을 하나님께 내어드리길 소망한다.

