4.주제 만들기: 가나안 땅을 정결하게 하라

5.하나님 찾기(관찰)
- 앞서 보낸 사자의 목소리를 청종하라
- 내 사자가 앞서 가서 너를 가나안 땅 사람에게로 인도하고
- 나는 그들을 끊을 것이다
- 너는 그들의 신을 경배하지 말고
- 네 하나님 여호와를 섬기라
- 그들을 쫓아낼 것이나 천천히 쫓아낼 것이다
-그들과 그들의 신들과 언약하지 말라
 
6.인간 찾기(관찰)

7.하나님 찾기(해석)
- 가나안 땅의 족속들을 쫓아내게 하시되 직접 인도하고 내쫓겠다고 말씀하심
- 하나님이 사람에게 명령하고 약속하신 것들은, 사람이 아니라 하나님께서 이루신다.
- 사람은 명령대로 행할 뿐이다.
- (이것은 마치 중요한 시험을 보는데, 하나님께서 답을 불러주시는 것과 같고
- 달리기 시합을 하는데, 하나님께서 뒤에서 밀어주는 것과 같다.)
- 이것은 사람의 성취인가? 아니다 하나님의 성취이다.

- 가나안 땅 족속들의 죄는 다른 신들을 음란히 섬긴 것이다.
- 그들의 죄가 가득 찼고, 이스라엘을 통하여 그들을 내쫓으시는 것이다.
- 하나님은 이스라엘도 가나안 땅 족속들의 죄를 범할까 염려하신다.

- 그들의 신들과 언약하지 말고,
- 가나안 족속들과도 언약하지 말라고 하신다.
- 신들과 언약하는 것은 우상 숭배하는 것이고,
- 그들과 언약하는 것은 그들을 살려주고 나아가 그들과 함께 살겠다는 것인데,
- 그렇게 되면 그들이 신들을 음란하게 섬기는 모습을 보고, 이스라엘도 물들까 염려하신 것이다.  
- 그들에게 물들면 이스라엘도 내쫓김 받는 신세가 될 것이기 때문이다. 

8.인간 찾기(해석)

9.적용(나) 
- 하나님께서 말씀하시면, 
- 그것이 두려운 일이라도 하나님을 의지하고 용기를 내어 나아가면 된다.
- 하나님이 계획하셨으니, 하나님이 반드시 성취하신다.

- 그렇다고 두려운 일을 두려운 줄 모르는 것도 안 된다.
- 그 일은 분명 두려운 일이다. 다만, 하나님께서 함께 하시니 담대하게 나아가는 것이다.

- 이방신을 섬기는 사람들에게 물들어서는 안된다.
- 구원에 있어서 타협은 없다.
- 오늘날 다른 신을 섬기는 사람들은 그리스도교는 편협하다고 말한다.
- 예수님을 통해서만 구원을 얻는다는 것이 말이 되느냐고, 자기네 종교에도 구원이 있다고 말한다.
- 그런데 그리스도교는 편협한 것이 아니라, 진리이다.

- 그리스도교를 편협하다고 주장하는 이들을 만나면,
- 준비된 말로 바르고 겸손하게 말할 줄 알아야 하며, 
- 나아가 은밀한 곳에서 그들을 긍휼히 여기며, 그들을 위해 기도해야 한다.
- 그들의 구원은 하나님께 있다.
 
10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-03-05', '출애굽기', '24장 1절~10절', '', '(출애굽기 24장)
1.  또 모세에게 이르시되 너는 아론과 나답과 아비후와 이스라엘 장로 칠십 명과 함께 여호와께로 올라와 멀리서 경배하고
2. 너 모세만 여호와께 가까이 나아오고 그들은 가까이 나아오지 말며 백성은 너와 함께 올라오지 말지니라
3. 모세가 와서 여호와의 모든 말씀과 그의 모든 율례를 백성에게 전하매 그들이 한 소리로 응답하여 이르되 여호와께서 말씀하신 모든 것을 우리가 준행하리이다
4. 모세가 여호와의 모든 말씀을 기록하고 이른 아침에 일어나 산 아래에 제단을 쌓고 이스라엘 열두 지파대로 열두 기둥을 세우고
5. 이스라엘 자손의 청년들을 보내어 여호와께 소로 번제와 화목제를 드리게 하고
6. 모세가 피를 가지고 반은 여러 양푼에 담고 반은 제단에 뿌리고
7. 언약서를 가져다가 백성에게 낭독하여 듣게 하니 그들이 이르되 여호와의 모든 말씀을 우리가 준행하리이다
8. 모세가 그 피를 가지고 백성에게 뿌리며 이르되 이는 여호와께서 이 모든 말씀에 대하여 너희와 세우신 언약의 피니라
9. 모세와 아론과 나답과 아비후와 이스라엘 장로 칠십 인이 올라가서
10. 이스라엘의 하나님을 보니 그의 발 아래에는 청옥을 편 듯하고 하늘 같이 청명하더라

