1:감동받는 단어나 구절 찾기(영적터치)

2025년 3월05일 
출애굽기 24장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
말씀/언약: 3절 4절 7절 8절 
피: 6절 8절 
가까이 나아오고/올라가서: 2절 9절
가까이 나아오지 말며/ 올라오지 말지니라: 2절
여호와: 2절 3절 8절 10절
모세: 1절 2절 3절 4절 6절 8절 9절

4.주제 만들기: 
피의 언약

5.하나님 찾기 (관찰)
모세에게 명령하시는 여호와.
모세와 사람들을 부르시는 여호와.
모세만 더 가까이 부르시는 여호와.
피의 언약을 준비시키는 여호와.

6.인간 찾기(관찰)
여호와 말씀에 순종하여 구분하여 여호와께 다가가는 모세와 사람들(아론과 나답과 아비후와 이스라엘 장로 칠십 명).
피의 언약의 제사를 준비하는 모세.

7.하나님 찾기(해석)
하나님은 피조물인 인간을 부르시고 만나 주시고 심지어는 피로 언약까지 체결하셨다. 
그 언약은 신과 인간의  영적 연합을 의미한다. 
최근 천문대를 다녀왔다. 그곳에서 우주 안의 은하수 강의를 화면으로 보았다. 

그리고 천문 망원경으로 직접 우주의 별 들을 가깝게 보았다. 보고 느끼는 것은 광활한 우주에 비해 지구는 정말 먼지처럼 작게 느꼈다. 
그러한 지구 안에 사는 인간은 우주하고 비교할 수 없을 정도로 작은 존재이다. 
그런데 모든 우주를 창조하신 하나님이 인간들을 언약의 피로 연합하시기를 원하신다는 것은 정말 이성적으로 이해하지 못할 정도로 감동적인 사건이다. 
특별히 독생자 예수님 보혈의 피로 죄인인 인간을 그저 믿기만 하면 존귀한 자로 받아주시고 자녀로 인정하사 안아주시는 사랑은 우주보다 크신 하나님의 마음인 것을 깨우친다.

8. 인간 찾기(해석)

9.적용(나):
주님이 보혈의 피로 세우신 언약을 더욱 소중히 여기며 살아야겠다.

10. 영적터치 (단어 또는 구절)
8절: 언약의 피니라.

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-03-06', '출애굽기', '24장 11절~18절', '여호와께서 모세를 시내산 꼭대기로 부르심', '출애굽기 24장
11   하나님이 이스라엘 자손들의 존귀한 자들에게 손을 대지 아니하셨고 그들은 하나님을 뵙고 먹고 마셨더라
12   여호와께서 모세에게 이르시되 너는 산에 올라 내게로 와서 거기 있으라 네가 그들을 가르치도록 내가 율법과 계명을 친히 기록한 돌판을 네게 주리라
13   모세가 그의 부하 여호수아와 함께 일어나 모세가 하나님의 산으로 올라가며
14   장로들에게 이르되 너희는 여기서 우리가 너희에게로 돌아오기까지 기다리라 아론과 훌이 너희와 함께 하리니 무릇 일이 있는 자는 그들에게로 나아갈지니라 하고
15   모세가 산에 오르매 구름이 산을 가리며
16   여호와의 영광이 시내 산 위에 머무르고 구름이 엿새 동안 산을 가리더니 일곱째 날에 여호와께서 구름 가운데서 모세를 부르시니라
17   산 위의 여호와의 영광이 이스라엘 자손의 눈에 맹렬한 불 같이 보였고
18   모세는 구름 속으로 들어가서 산 위에 올랐으며 모세가 사십 일 사십 야를 산에 있으니라

