6.인간 찾기(관찰)
- 모세와 이스라엘의 지도자들이 하나님 앞에서 먹고 마심
- 모세가 여호수아와 함께 산으로 올라감
- 모세가 사십 일 사십 야를 산에 있음

7.하나님 찾기(해석)
- 하나님께서 특별히 이스라엘 지도자들 앞에 임재하시고,
- 앞에서 먹고 마시게 해주심
- 계명과 율법이 적힌 돌판을 주시기 위해 모세를 부르심

- 이스라엘 모든 사람이 하나님께서 산에 임재한 것을 알았지만,
- 모든 사람이 하나님 앞에서 먹고 마시지는 않음
- 지도자들이 하나님 앞에서 먹고 마셨으나,
- 지도자 모두가 돌판을 받으러 올라가지 않고,
- 모세만 올라감

- 하나님께서 원하시는 위계질서가 있음을 알 수 있음 

8.인간 찾기(해석)
- 하나님 앞에 섰으나 죽지 않고 하나님 앞에서 먹고 마신 지도자들은 
- 하나님의 위대하심과 사랑을 경험하고 하나님을 더욱 경외하게 되었을 것
- 모세는 여호수아와 함께 산으로 올라간 것으로 보아,
- 모세가 여호수아를 얼마나 아꼈는지 알 수 있음

9.적용(나) 
- 모세 때에 죽지 않고 하나님 앞에서 먹고 마시는 것은 대단한 영광이었다.
- 오늘날 신자는 하나님의 영이 거하는 성전이고 
- 동시에 예수님과 더불어 먹고 마시는 존재이다.
- 이것을 기억하고 하나님께 감사와 찬송을 올려드려야 한다.

