2 이스라엘 자손에게 명령하여 내게 예물을 가져오라 하고 기쁜 마음으로 내는 자가 내게 바치는 모든 것을 너희는 받을지니라
3 너희가 그들에게서 받을 예물은 이러하니 금과 은과 놋과
4 청색 자색 홍색 실과 가는 베 실과 염소 털과
