6 등유와 관유에 드는 향료와 분향할 향을 만들 향품과
7 호마노며 에봇과 흉패에 물릴 보석이니라
8 내가 그들 중에 거할 성소를 그들이 나를 위하여 짓되
9 무릇 내가 네게 보이는 모양대로 장막을 짓고 기구들도 그 모양을 따라 지을지니라
10 그들은 조각목으로 궤를 짜되 길이는 두 규빗 반, 너비는 한 규빗 반, 높이는 한 규빗 반이 되게 하고

