4. 주제만들기: 성소를 짓기 위해 자발적으로 드리는 예물
5. 하나님 찾기 (관찰)
- 이스라엘 자손에게 명령하여 예물을 가져오라 하심
- 모세에게 보이는 모양대로 장막과 기구를 짓게 하심
6. 인간 찾기 (관찰)
- 기쁨 마음으로 예물을 하나님께 바침
7. 하나님 찾기 (해석) 
- 하나님은 성소를 짓기 위해 예물을 가져오라 하시는데 기쁜 마음으로 바치는 것을 말씀하셨다. 기쁜 마음은 하나님을 나의 주인이심을 믿고 완전한 순종의 감정일 것이다. 하나님은 예물의 많고 적음을 요구하신게 아니라 기쁜 마음을 요구하셨다. 하나님의 명령에 기쁜 마음으로 감당하는 태도가 중요함을 깨닫는다.
8. 인간(해석):
- 하나님의 명령에 이스라엘 백성은 기쁜 마음으로 다양한 보물을 드렸다. 보물은 성소를 짓는 재료가 되었고, 하나님께 드리는 것에 불평하거나 불만을 보이는 백성이 없다. 오래가진 않았지만 이스라엘 백성에게도 기쁜 마음이 있었다. 중요한 사실은 인간은 기쁜 마음을 품었다가 변할 수 있다는 점이다. 
- 기쁜 마음이라는 것은 스스로 즐거운 마음으로 예물을 드렸다는 것인데, 영적으로 거룩한 상태라는 것임을 알 수 있다. 그러나 그런 순간도 쉽게 사그러들 수 있다. 그렇기 때문에 우리는 영적 거룩한 상태를 유지할 수 있는 민감함과 노력이 필요하다.
9. 적용(나): 
- 하나님께선 완전한 순종을 요구하신다. 주님 앞에 순종해야할 것들이 많은데 기도와 말씀을 통해 주님의 뜻을 깨달아야겠다.
- 영적 거룩한 상태를 유지하기 위해 노력하자.
10. 영적터치(단어/구절)
- 기쁜 마음
