4.주제 만들기: 
궤와 증거판

5.하나님 찾기 (관찰)
증거궤에 대한 제작과 그 안에 들어갈 증거판에 대하여 말씀하시는 여호와.

6.인간 찾기(관찰)
여호와의 말씀을 듣는 모세.

7.하나님 찾기(해석)
하나님은 궤를 무엇보다 화려하고 품위 있게 만들 것을 주문하셨다.

 순금으로 테두리를 두르고 또한 온통 금으로 두르게 하셨다. 

고리도 금으로 만들어 여러 사람이 안전하게 들도록 하셨다. 

하나님은 증거궤를 우아하고 값지게 만드신 이유는 무엇일까? 

그것은 궤 안에 들어갈 증거 판 때문이다. 즉 하나님의 말씀이기 때문이다. 

화려함으로 꾸민 궤도 사실 하나님 말씀을 돋보이기 위한 화려한 장식이라 한다면 말씀이야말로 얼마나 소중하고 귀한 것인지를 묵상하게 된다. 

증거궤는 화려한 옷이라 하면 하나님 말씀은 사람을 살리는 생명과도 같다고 볼 수 있다. 

그러한 생명의 말씀을 현대를 사는 자녀들은 더욱 소중히 다루고 귀하게 여기는 마음을 가지는 것은 하나님에 대한 기본적 도리인 것 같다.

8. 인간 찾기(해석)

9.적용(나):
하나님이 말씀을 귀하게 여기시듯이 나도 더욱 말씀을 사랑하며 늘 묵상하는 삶을 살아내야겠다.

