7.하나님 찾기(해석)
하나님은 모세에게 지성소에 들어갈 언약궤를 만들 것을 주문하셨다. 

언약궤 안에는 증거 판을 넣도록 명령하셨다. 언약궤 윗부분인 속죄 소(궤의 뚜껑)의 만들라고 하셨다. 

그때 그곳에서 하나님은 만나 주시고 이스라엘 백성들을 위하여 명령하신다고 말씀하신다. 

언약궤의 만드신 하나님의 목적은 인간과 깊은 교제 즉 관계를 갖고자 여겨진다. 

이스라엘 백성들을 ''위하여''를 보면 인간을 사랑하심을 알 수 있다. 특히 궤 안과 밖으로 순금을 많이 사용하신 것과 속죄 소를 궤의 뚜껑으로 사용하신 것을 보면 하나님의 거룩하시고 정결하신 성품을 쉽게 알 수 있다. 

언약궤의 규격도 친히 정하신 것 보면 섬세하신 손길도 알 수 있다. 그 섬세함으로 우리의 작은 신음에도 반응 하시고 응답하여 주심에 큰 위로가 된다. 

또한 하나님은 거룩하시고 사람을 사랑하시고 함께 교제하기를 원하심이 언약궤 만드시는 과정에서 증명되는데 특히 속죄 소 부분에서 하나님의 임재를 경험할 수 있다는 것이다. 

속죄 소(언약궤의 덮게)라 하면 인간의 회개를 통한 용서받음이 먼저 이루어진 후 거룩하신 하나님과의 교제의 장소라고 생각된다. 

이런 부분을 생각할 때 당시 대제사장이 일 년에 한 번씩 언약궤가 있는 지성소에 들어가는 형태를 현대와 비교할 때 지금은 얼마나 쉽게 영적 교제를 할 수 있는지 알 수 있다.

8. 인간 찾기(해석)

9.적용(나):
하나님 말씀을 늘 소중히 여기며 주님과 더욱 영적 깊은 교제하기를 힘써야겠다.

10. 영적터치 (단어 또는 구절)
22절: 거기서 내가 너와 만나고

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

