- 가늘게 꼰 베실과 청색, 자색, 홍색 실로 정교하게 수놓게 하심
- 청색은 하늘을, 자색은 왕권을, 홍색은 속죄를 뜻한다고 볼 수 있다.
- 하늘의 영광과 왕권과 속죄는 모두 하나님께 속한 것이다.
- 이스라엘 백성은 휘장을 통해 하나님의 영광과 왕권과 속죄에 대해 더 생각하게 됐을 것이다.
 
