- 하나님의 영광의 본체이시고, 만왕의 왕이신 분께서 나를 속죄하고 구원하시려고 이 땅에 내려오셨다.
- 그리고 지금 성령님께서 내주하심으로 나와 동행하신다.
- 이 놀라운 일을 늘 기억하고, 늘 감사하며 살아야 한다.

