4.주제 만들기: 
성막

5.하나님 찾기 (관찰)
성막 설계를 구체적으로 말씀 하시는 여호와.

6.인간 찾기(관찰)
여호와의 말씀을 듣는 모세.

7.하나님 찾기(해석)
성막 안에 있는 휘장은 예수님의 몸이라고 히브리서에 기록되었다(10장20절: 휘장은 곧 그의 육체니라). 

성막은 천국 성전의 모형이라고 할 때 천국의 성전이 얼마나 아름다울까 상상되지 않는다. 

하나님은 광야에 있는 인생들에서 성막을 통하여 천국의 소망을 의도적으로 느끼게 하시는 것 같다. 

특별히 거룩한 성막을 설계하실 때 덮는 재료로 붉은 물 들인 숫양의 가죽과 해달의 가죽으로 사용하시라고 명령하셨다. 

생각할 때 붉은 물 들인 숫양은 ‘보혈’을 의미함을 생각한다. 즉 하나님의 사랑의 헌신 은혜 그 자체인 것 같다. 늘 우리의 허물의 회개를 통하여 덮어주심을 생각한다. 

또한 하나님은 재료를 덮개로 선택하실 때 수소 외에 수많은 동물 중에 왜 해달을 선택하셨을까? 족제비과에 속하는 해달은 수중에서 주로 살며 털가죽이 보온에도 강하고 속 가죽은 매우 부드럽다고 하는 것을 볼 때 이동식 예배당인 성막을 중동의 추위와 모래바람으로부터 보호하기 적절한 것 같다. 

섬세함과 모든 피조물을 창조하신 하나님의 지혜에 큰 감명을 받는다. 그러한 하나님이 늘 우리 곁에서 우리의 영혼을 지켜주심에 감사와 동시에 큰 위로가 된다. 
8. 인간 찾기(해석)

9.적용(나):
섬세하게 보호하시고 설계하시는 하나님 성품처럼  나도 사역과 섬김에 더욱 깊은 관심을 가져야겠다.

10. 영적터치 (단어 또는 구절)
