5.하나님 찾기 (관찰)
제단 설계를 구체적으로 말씀 하시는 여호와.

6.인간 찾기(관찰)
여호와의 말씀을 듣는 모세.

7.하나님 찾기(해석)
불 제단은 고대로부터 하나님의 공의 와 심판을 상징하는 동시에 속죄와 회복의 장소라고 하고 있다. 

즉 죄인들이 회개를 통한 거룩하신 하나님과의 만남을 갖도록 하는 제사를 올리는 곳이라 할 수 있다. 제단은 보존성을 위하여 제단을 놋(구리) 재료로 사용하였다. 

제단 위의 뿔은 하나님의 힘과 권위 그리고 구원을 상징함을 알 수 있다. 구약성경 시편에 보면 기자들이 "구원의 뿔"이라고 기록한 것을 쉽게 볼 수 있다. 당시 죄인이 목숨을 지키기 위해 그곳으로 달려가 뿔을 잡고 용서를 구할 때 목숨을 보장받는 도피처로도 쓰였다. 

구약의 제단과 뿔을 통하여 예수님의 구원 십자가의 사랑과 헌신 구원을 예표 됐다고 볼 수 있다. 

죄인이 된 나를 위하여 대신 돌아가시고 나를 용서하사 살리신 주님의 사랑을 더욱 느끼게 된다.

8. 인간 찾기(해석)

