6.인간 찾기(관찰)


7.하나님 찾기(해석)
''뜰''은 성전 안에서 이스라엘 백성과 하나님과의 영적 교제하는 장소라고 할 수 있디. 

현대 교회 안의 성도의 예배드리는 자리인 듯하다. 하나님은 또한 등불을 꺼지지 않도록 명령하셨다. 

등불 안에 기름은 순수한 기름을 준비하라고 하셨다. 꺼지지 않는 깨끗한 등불을 여호와 앞에 준비하라고 하신 이유는 무엇일까?

마치 마태복음 25장에 등장하는 열 처녀 비유하고도 비슷한 내용인 것을 느낀다. 아마도 성전 안의 뜰은 하나님과의 지속해 만남과 순수한 사랑을 의미하는 것 같다. 

온전한 믿음과 사랑 그리고 순종으로 드리는 예배를 누구보다 하나님은 원하고 계신다. 꺼지지 않는 등불처럼 하나님은 이스라엘 백성뿐만 아니라 영적 자녀들과 영원히 함께하시기를 원하시지를 깨우친다. 

믿는 자들은 예배의 가치를 안다면 더욱 사모하는 마음이 생길 것이다.

8. 인간 찾기(해석)

9.적용(나):
꺼지지 않는 등불처럼 늘 주님을 향한 믿음이 식지 않도록 더욱 영적인 생활을 해야겠다.

