5. 하나님 찾기 (관찰)
- 모세에게 형 아론과 그의 아들들이 하나님을 섬기기 위한 제사장 직분 수행하게 하시며 거룩한 옷을 만들게 하심

6. 인간 찾기 (관찰)

7. 하나님 찾기 (해석)
- 하나님께서 제사장 직분을 수행하도록 특별히 아론과 그의 아들들을 택하셨다. 모세와 동역하며 하나님께 제사드릴 수 있는 직분을 얻게 함으로써 아론을 이스라엘 백성 가운데 세워주셨다.
- 하나님은 제사장의 옷을 거룩하고 지혜로운 영으로 제작하도록 명령하셨다. 두가지 상징적인 의미를 생각해볼 수 있는데, 하나님의 거룩하심과 제사장의 거룩한 구별이다. 하나님께서 거룩하시기 때문에 하나님이 거하시는 곳과 하나님을 만나러 오는 사람은 거룩해야 한다. 
- 현 시대를 살아가는 우리는 더 좋은 환경과 장소에서 예배하고 있다. 그러나 얼마나 거룩함을 갖고 하나님을 예배하는지 점검해볼 필요가 있다.  

8. 인간(해석):
- 아론은 모세와 함께 하였더니 제사장 직분을 받게 되었다. 그리고 성경에 기록되는 영광도 누리게 되었다. 우리는 누구와 함께하는지 중요하다. 지금 내가 하나님을 갈망하는 사람들과 함께한다면 그보다 큰 축복이 있을까? 

9. 적용(나): 
- 예배의 거룩함이 회복되길 소망한다.
- 하나님을 사랑하는 사람들을 곁에 주신 것에 감사하고, 나도 누군가에게 하나님을 사랑하는 한 사람으로서 역할을 감당해야겠다.

