4.주제 만들기: 에봇의 설계도
5.하나님 찾기(관찰)
- 이스라엘의 열두 아들의 이름을 새긴 두 보석을 에봇의 어깨받이에 붙이게 하심
- 판결 흉패에 이스라엘의 열두 아들을 상징하는 보석을 열두 개 붙이게 하심
6.인간 찾기(관찰)
7.하나님 찾기(해석)
- 에봇은 대제사장인 아론과 그의 후손들이 입을 옷이다.
- 그 옷의 어깨받이에 이스라엘의 열두 아들의 이름을 새겨 
- 하나님께서 기억하신다고 하셨다.
- 열두 아들을 기억한다는 것은 이스라엘 민족을 기억하신다는 것이며,
- 이것은 언약을 기억하시고 그들을 속죄, 구원하시겠다는 것이다.
- 판결흉패에 열두 가지 보석을 붙이는데 이 열두 보석 또한 이스라엘의 열두 아들,
- 즉 열두 지파, 이스라엘 민족을 의미한다.
- 하나님께서는 이스라엘의 열두 아들의 이름과 그들의 지파를 상징하는 보석을 에봇에 붙이시고 그들을 기억하겠다고 말씀하셨다.
- 이것은 그들의 후손 모두를 기억하고 구원하시겠다는 것이다.
- 대제사장은 진정한 대제사장이신 예수님을 예표한다.
- 이를 통해 하나님께서는 새 이스라엘, 
- 그리스도인(신자) 모두를 기억하고 구원하신다는 것을 알 수 있다.
- 구약에는 에봇을 보고 이스라엘을 기억하고 속죄하셨다면,
- 신약에는 예수님을 보고 신자들을 기억하고 속죄하시는 것이라 볼 수 있다.
- 이스라엘 아들(모든 후손)의 이름을 귀한 보석에 새기시고, 
- 아들을 상징하는 보석을 판결흉패에 붙이셨다.
- 모든 신자는 하나님이 보시기에 아름다운 보석이다.
- 우리는 하나님께 아름답고 귀한 보석이다.
8.인간 찾기(해석)
9.적용(나)
- 하나님께서 나를 사랑하셔서 보석으로 여기신다.
- 나를 귀히 여기시고 너무나 사랑하시는 하나님을 찬양해야겠다.
- 예수님이 이 땅에 안 오셨다면 어쩔 뻔했는가.
- 진정한 대제사장이신 예수님을 바라보며,
- 오늘 하루도 감사하며, 기뻐하며 살아가야겠다.
