4.주제 만들기: 
팔결 흉패

5.하나님 찾기 (관찰)
판결 흉패를 설계하시는 여호와.

6.인간 찾기(관찰)
여호와의 말씀을 받는 모세.

7.하나님 찾기(해석)
구속자 되신 하나님의 ''의'' 를 제사장의 예복의 설계도를 보면서 쉽게 알 수 있다. 

21절에 "열두 지파의 한 이름씩 도장을 새기는 법으로 새기고" 기록된 것을 보면 법으로 이름을 새길 정도로 자녀들의 구원을 간직하시는 의지를 볼 수 있다. 

29절 기록내용 또한 "아들들의 이름을 기록한 이 판결 흉 패를 가슴에 붙여"로 기록된 것을 보면 마찬가지로 생명록에 구원이 이미 도래된 것을 알 수 있다. 

기록 시점 이후로 오실 예수님을 예표 함을 알 수 있다. 구원과 동시에 우리 삶을 성장시키고 인도하시고자 하는 하나님의 뜻을 또한 발견한다. 

30절에 제사장 온 흉패 안에 들어갈 ''우림과 둠밈''을 기록하였다. 우림의 본뜻은 ''빛들''이고 둠밈은 ''온전함''이라고 할 때 ‘빛과 공의’라 볼 수 있다. 실제로 당시 제사장이 전반적인 큰 문제를 두고 결정할 때 주로 이 ''우림과 둠밈'' 이 들어간 흉패 옷을 입고 제비뽑기를 하여 결정했었다고 한다. 

 현대 교회 성도들은 대부분 결정할 일이 있는 경우 성경 말씀과  이미 함께하신 성령님께 구하고 간청하는 기도로 한다. 

예전과 달리 다소 방식은 조금 다르지만, 자녀를 사랑하사 구원하시고 옳은 길로 인도하시고자 하시는 하나님의 의지와 사랑하심의 본질은 변함이 없으시다.

8. 인간 찾기(해석)


