- 한편 금방울 소리가 나지 않으면 죽는다고 하셨다.
- 우리에게 금방울 소리는 예수님의 말씀이고 기도일 것이다.

- 그리스도인은 예수님의 생명의 충만함을 누리되,
- 말씀에 집중하고 신중하게 행동해야 한다. 

- 여호와께 성결이라는 글씨를 패에 쓰고 그것을 머리에 쓰는 관에 매도록 함
- 그리스도인은 거룩하게 구별된 삶을 살아야 한다.

- 아론과 아들들은 속바지를 입어 하체를 가려야 함 
