7. 하나님 찾기 (해석)
- 제사장 직분을 섬기기 위해 거룩함이 요구된다. 요즘과 같은 시대에서 형식을 통해 거룩한 행위를 보여야 한다면 이 과정이 우리를 괴롭게 했을 것이다. 그만큼 우리가 거룩함을 유지하기 위해선 힘들고 어려운 과정을 거쳐야 정결해 질 수 있다.
- 우리는 예수님을 통해 이러한 과정을 거치지 않아도 의롭다 함을 인정 받을 수 있게 되었다. 그렇다고 우리가 의롭거나 거룩하지 않다. 단지 예수님을 통해서 비교적 쉬운 방법인 것처럼 느껴질 뿐이다. 우리는 거룩함을 유지할 수 없다. 유지한다고 착각하는 것뿐이다. 그렇기 때문에 늘 겸손한 마음으로 하나님의 은혜에 감사하며 순종해야 한다. 
