출애굽기 29장21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
요제/요제물: 24절 26절 27절 
거제물: 28절(2)
숫양: 22절(2) 26절 27절 
분깃: 26절 28절 
번제물/화제: 25절
거룩: 21절 27절 
여호와: 25절 26절 28절 

4.주제 만들기: 
거룩한 제사

5.하나님 찾기 (관찰)
 제사장 아론에게 제사를 가르치시며 아론의 아들들에게 영적 제사장의 계승을 명령하시는 여호와.

6.인간 찾기(관찰)
여호와의 말씀을 받는 모세.

7.하나님 찾기(해석)
여호와 하나님이 제단 위의 피와 관유(기름)를 제사장의 가족(아론) 옷에 뿌리라 함의 의미는 무엇일까?

 당연히 거룩함과 구분됨이라 확실시된다. 제사장 아론 뿐만 아니라 아들들의 옷에도 피와 기름을 뿌린다는 지속적인 영적 계승을 의미하는 것이다. 

2025년도에 사는 믿는 자들도 그러한 거룩함과 구분됨의 특권과 책임감이 있음을 알 수 있다.

또한 속죄물을 요제의 방식으로 흔들라 하심은 온전한 헌신과 하나님의 은혜라고 생각할 때 하나님께서 인간들과 얼마나 깊은 관계성을 갖기를 원하시는지 알 수 있다.

특별히 제사장 아론에게 ''영원한 분깃''이라는 선물을 주실 때는 더욱 느끼게 된다. 하나님은 영원토록 우리와 함께하시기를 깨우치게 된다. 

그 부분을 충족하기 위해서는 우리 또한 거룩한 사람이 돼야 하는데 결코 쉬운 일은 아닌 것 같다. 

그러나 가능케 될 수 있는 것은 대제사장이신 예수께서 이미 보혈로 우리 죄를 속량하시사 누구든지 진심으로 회개하고 주님을 믿는다면 거룩한 백성으로 받아주시는 하나님의 은혜가 있기 때문이다. 

''요거제'' 의식처럼 우리의 헌신을 흔들어 아낌없이 주님께 드리려는 삶이 복된 삶은 것이 제사장의 삶은 것 같다.

8. 인간 찾기(해석)


9.적용(나):
자녀들에게 좋은 영적 계승자가 되도록 더욱 노력해야겠다.
딸들이 큐티와 개인 기도를 열심히 하도록 더욱 관심을 가져야겠다.

10. 영적터치 (단어 또는 구절)
28절: 영원한 분깃

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-03-24', '출애굽기', '29장 31절~40절', '거룩한 식사', '[출29:31-40]
31 너는 위임식 숫양을 가져다가 거룩한 곳에서 그 고기를 삶고
32 아론과 그의 아들들은 회막 문에서 그 숫양의 고기와 광주리에 있는 떡을 먹을지라
33 그들은 속죄물 곧 그들을 위임하며 그들을 거룩하게 하는 데 쓰는 것을 먹되 타인은 먹지 못할지니 그것이 거룩하기 때문이라
34 위임식 고기나 떡이 아침까지 남아 있으면 그것을 불에 사를지니 이는 거룩한즉 먹지 못할지니라
35 너는 내가 네게 한 모든 명령대로 아론과 그의 아들들에게 그같이 하여 이레 동안 위임식을 행하되
36 매일 수송아지 하나로 속죄하기 위하여 속죄제를 드리며 또 제단을 위하여 속죄하여 깨끗하게 하고 그것에 기름을 부어 거룩하게 하라
37 너는 이레 동안 제단을 위하여 속죄하여 거룩하게 하라 그리하면 지극히 거룩한 제단이 되리니 제단에 접촉하는 모든 것이 거룩하리라
38 네가 제단 위에 드릴 것은 이러하니라 매일 일 년 된 어린 양 두 마리니
39 한 어린 양은 아침에 드리고 한 어린 양은 저녁 때에 드릴지며
40 한 어린 양에 고운 밀가루 십분의 일 에바와 찧은 기름 사분의 일 힌을 더하고 또 전제로 포도주 사분의 일 힌을 더할지며

