4. 주제만들기: 거룩한 식사


5. 하나님 찾기 (관찰)
- 회막 문 앞에서 고기와 떡을 먹게 하시는 하나님
- 이레 동안 이임식을 명하신 하나님


6. 인간 찾기 (관찰)


7. 하나님 찾기 (해석) 
- 하나님께선 회막에서 고기와 떡을 먹게하셨다. 그 분의 임재 아래, 속죄의 제물을 드린 후 식사를 통해 우리를 회복시키셨다. 예수님 이전에는 거룩한 제사장만 누릴 수 있던 은혜를 예수님을 통해 누구나 누릴 수 있는 은혜가 되었다. 나는 예수님과의 만찬을 얼마나 소중히 여기고 있을까?
- 일년 된 흠 없는 어린 양은 가장 좋은 최상의 상태일 것이다. 그런 양을 하루에 두 번이나 드리며 속죄제를 드리게 하셨다. 십자가를 지시기 전, 예수님의 공생애 사역들은 최상의 상태였다. 누구나 이 땅에 오신 구원자라 생각하며 그 분을 따를 정도로 대단하셨다. 그러나 예수님은 스스로를 속죄 제물로 여기시고 십자가를 지셨다. 인간이 바라는 왕이 아닌, 하나님께서 바라는 왕이 되신 것이다. 예수님의 사랑과 은혜에 감사하다.


8. 인간(해석):


9. 적용(나): 
- 예수님과의 만찬을 소중히 여기고, 거룩한 예배를 드리는 일에 게으르지 말자.
- 예수님을 통해 받은 사랑과 은혜를 많은 사람에게 전하자. 이제는 멸시하고 무시하는 표정이 두렵지 않다.


10. 영적터치(단어/구절)
- 어린 양
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-03-25', '출애굽기', '29장 41절~46절', '이스라엘을 구원하신 이유', '출애굽기 29장
41   한 어린 양은 저녁 때에 드리되 아침에 한 것처럼 소제와 전제를 그것과 함께 드려 향기로운 냄새가 되게 하여 여호와께 화제로 삼을지니
42   이는 너희가 대대로 여호와 앞 회막 문에서 늘 드릴 번제라 내가 거기서 너희와 만나고 네게 말하리라
43   내가 거기서 이스라엘 자손을 만나리니 내 영광으로 말미암아 회막이 거룩하게 될지라
44   내가 그 회막과 제단을 거룩하게 하며 아론과 그의 아들들도 거룩하게 하여 내게 제사장 직분을 행하게 하며
45   내가 이스라엘 자손 중에 거하여 그들의 하나님이 되리니
46   그들은 내가 그들의 하나님 여호와로서 그들 중에 거하려고 그들을 애굽 땅에서 인도하여 낸 줄을 알리라 나는 그들의 하나님 여호와니라

