4.주제 만들기: 이스라엘을 구원하신 이유

5.하나님 찾기(관찰)
- 날마다 드려야 하는 번제에 대해 말씀하심
- 회막 앞에서 만나주시고 말씀하실 것을 말씀하심
- 이스라엘 자손 중에 거하여 그들의 하나님이 되겠다 말씀하심

6.인간 찾기(관찰)

7.하나님 찾기(해석)
- 번제를 드리되 매일, 아침과 저녁 두 번씩 드리도록 명하심
- 인간은 날마다 주야로 하나님을 예배해야 함. 
- 오늘날 우리는 성령님을 의지하여 말씀과 기도로 개인적인 예배를 드릴 수 있음.

- 거기서 너희와 만나고 말하겠다 하심
- 오늘 우리가 날마다 예배를 드리면, 하나님은 우리를 만나 주시고 말씀해 주실 것임.

- 하나님의 영광으로 말미암아 회막이 거룩하게 된다.
- 거룩은 하나님께로부터 오는 것이다.
- 우리는 거룩하게 살기 위해 하나님의 영광을 늘 바래야 한다.

- 하나님은 이스라엘 자손 중에 거하시려고 그들을 애굽에서 인도하여 내셨고,
- 그것을 이스라엘 자손들이 알기를 원하신다.

- 하나님은 이스라엘 백성을 사랑하셔서 구원하시고 함께 하시길 원하신다.
- 이 하나님이 우리를 사랑하셔서,
- 예수님이 성육신하시고 십자가를 담당하시고, 
- 부활 승천하셔서, 지금 성령 하나님이 우리와 함께 하신다.

- 그리고 영원히 우리와 함께 하실 것이다.
- 하나님은 이것을 우리가 알기를 원하신다.

8.인간 찾기(해석)

9.적용(나) 
- 주야로 주의 말씀을 묵상하고 그것을 읇조리며 살아야 한다.
- 하나님의 영광을 구하며, 거룩을 추구하며 살아야 한다.
- 임마누엘 하나님께 감사를 드리며, 이것을 누리며 살아야 한다.

