2025년 3월26일 
출애굽기 30장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
제단: 1절 4절 
뿔: 2절 3절 10절
향/향기: 7절 8절 9절
속죄: 10절(3)
속죄소: 6절(2)
일 년에 한 번씩: 10절(2)

4.주제 만들기: 
일 년에한 번씩 드리는 속죄제

5.하나님 찾기 (관찰)
분향할 제단에 대하여 설명하시는 여호와.
일 년에 한 번씩 올릴 속죄제를 가르치시는 여호와.

6.인간 찾기(관찰)
여호와의 말씀을 받는 모세.

7.하나님 찾기(해석)
8절의 말씀처럼 “또 저녁때 등불을 켤 때에 사를지니 이 향은 너희가 대대로 여호와 앞에 끊지 못할지며” 하나님은 대대로 인간들과 영적 교제를 원하심을 알 수 있다. 

다만 누구든지 제단 앞 등불과 향기가 끊어지지 않게 함을 강조하신다. 즉 등불은 말씀이라면 향기는 기도라 생각이 든다. 

늘 우리 삶에 말씀과 기도로 하나님의 임재가 있어야 함을 강조하신 것 같다. 

또한 번제나 소제 같은 제사가 아닌 아론이 일 년에 한 번씩 드리는 제사라고 하는 것을 보면 개인이 아닌 국가나 백성이 지은 죄를 회개함을 보여주는 것 같다. 

사실 가족이나 공동체를 위하여 중보기도는 많이 하는데 국가를 위하여 더욱 기도해야 함을 깨우친다. 

그래서 예수님의 보혈과 선교사들의 헌신으로 세워진 대한민국을 위하여 더욱 하나님께 인정받고 선교적 사명을 갖고 쓰임 받는 나라가 되기를 바란다. 

8. 인간 찾기(해석)


9.적용(나):
대한민국이 더욱 복음적이고 선교적 사명을 잘 감당하는 국가로 나아가도록 더욱 기도해야겠다.

10. 영적터치 (단어 또는 구절)
