4.주제 만들기: 우상을 부어 만든 이스라엘

5.하나님 찾기(관찰)
- 모세에게 금송아지를 만든 이스라엘 백성에 대해 말씀하시며, 
- 이스라엘 백성을 멸하겠다 말씀 하심

6.인간 찾기(관찰)
- 모세가 내려오지 않자 우상을 만들어 달라고 요청하는 이스라엘 백성들
- 백성들의 말을 듣고 우상을 만드는 아론
 
7.하나님 찾기(해석)
- 이스라엘 백성을 사랑하셔서 그들의 예배와
- 그들의 하나님이 되기를 원하셔서
- 그들을 애굽에서 인도하여 내셨는데,
- 겨우 40일을 못 참고 우상을 만들어 음란히 섬기는 백성들을 봄
- 애굽 바로에게 하셨던 표현과 똑같이 목이 뻣뻣하다는 말씀을 하심
- 목이 뻣뻣하다는 것은 고집이 세다는 표현으로
- 아직도 하나님이 하나님 됨을 인정하지 못하고 
- 자신을 위해 우상을 만든 백성을 향해 하신 말씀이다
- 오늘날 그리스도인도 목이 뻣뻣하지 않도록 회개하고 주의해야 한다   
- 하나님은 진노하셨고 이스라엘을 진멸하고 모세를 통해 큰 민족을 세우겠다 말씀하심

8.인간 찾기(해석)
- 모세가 내려오지 않자 이스라엘 백성이 불안하여 우상을 만들어 달라고 함
- 불안함과 두려움도 있었겠으나,
- 거룩한 생활보다는 음란한 생활을 그리워하는 사람들이 섞여 있었고,
- 그들이 우상을 만들자고 여론을 조성했을 가능성도 있음
- 아론은 이 말을 듣고 거절하고 회개의 기도를 하도록 중심을 잡았어야 하지만,
- 그렇게 하지 못하고 그 제안을 받아들임
- 모든 백성이 귀에 달고 있는 금고리들을 우상을 만드는 재료로 사용해 버림
- 이것은 하나님이 주신 선물로 우상을 만든 것으로서 있어서는 안 되는 일이었음
- 애굽의 문화를 그대로 가져와 하나님의 절일에 번제를 드리며 음란히 섬김 

9.적용(나) 
- 사람들의 말을 듣고 움직일 때가 많은데,
- 하나님의 나라와 의에 합한 것일 때만 그 말을 듣고 움직여야겠다.

- 지금 내 목이 뻣뻣하지 않는가 점검해야 한다.
- 하나님이 나의 하나님되심을 인정하지 않고,
- 내가 주인 삼은 것이 있지는 않은지 잘 살펴보고 없애야겠다. 

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-01', '출애굽기', '32장 11절~20절', '', '.(출애굽기 32장)
11. 모세가 그의 하나님 여호와께 구하여 이르되 여호와여 어찌하여 그 큰 권능과 강한 손으로 애굽 땅에서 인도하여 내신 주의 백성에게 진노하시나이까
12. 어찌하여 애굽 사람들이 이르기를 여호와가 자기의 백성을 산에서 죽이고 지면에서 진멸하려는 악한 의도로 인도해 내었다고 말하게 하시려 하나이까 주의 맹렬한 노를 그치시고 뜻을 돌이키사 주의 백성에게 이 화를 내리지 마옵소서
13. 주의 종 아브라함과 이삭과 이스라엘을 기억하소서 주께서 그들을 위하여 주를 가리켜 맹세하여 이르시기를 내가 너희의 자손을 하늘의 별처럼 많게 하고 내가 허락한 이 온 땅을 너희의 자손에게 주어 영원한 기업이 되게 하리라 하셨나이다
14. 여호와께서 뜻을 돌이키사 말씀하신 화를 그 백성에게 내리지 아니하시니라
15. 모세가 돌이켜 산에서 내려오는데 두 증거판이 그의 손에 있고 그 판의 양면 이쪽 저쪽에 글자가 있으니
16. 그 판은 하나님이 만드신 것이요 글자는 하나님이 쓰셔서 판에 새기신 것이더라
17. 여호수아가 백성들의 요란한 소리를 듣고 모세에게 말하되 진중에서 싸우는 소리가 나나이다
18. 모세가 이르되 이는 승전가도 아니요 패하여 부르짖는 소리도 아니라 내가 듣기에는 노래하는 소리로다 하고
19. 진에 가까이 이르러 그 송아지와 그 춤 추는 것들을 보고 크게 노하여 손에서 그 판들을 산 아래로 던져 깨뜨리니라
20. 모세가 그들이 만든 송아지를 가져다가 불살라 부수어 가루를 만들어 물에 뿌려 이스라엘 자손에게 마시게 하니라

