2025년 4월2일 
출애굽기 32장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
어찌하여: 11절 12절 
금 송아지: 19절 20절
모세: 11절 15절 18절 20절
여호와: 11절 12절 14절 
진노/화/진멸: 11절 12절  14절
뜻을 돌이키사/백성에게 내리지아니하시니라: 14절

4.주제 만들기: 
모세의 변호로 심판의 계획을 멈추신 여호와.

5.하나님 찾기 (관찰)
진노하시는 여호와.
심판 계획을 멈추신 여호와.


6.인간 찾기(관찰)
진노하시는 하나님께 자비를 구하는 모세.
돌판을 깨뜨리는 모세.
금 송아지를 불살아 부수는 모세. 


7.하나님 찾기(해석)
 
8. 인간 찾기(해석)
모세는 큰 나라의 시조가 될 기회를 거부하였다. 

우상 송아지 만든 아론과 이스라엘 백성들을 향하여 분노하신 여호와께서 아브라함과 맺은 약속을 파기하시고 모세를 시발점으로 새로운 민족을 다시 건설하려 하신다고 하셨었다. 

당시 하나님이 얼마나 진노가 높으셨던 가를 쉽게 가늠할 수 있다. 그러나 모세는 본래 여호와의 마음을 잘 살피고 있었다. 

자신의 높아짐보다 하나님의 명예를 진심으로 생각하는 동시에 형 아론과 이스라엘 백성들의 영혼을 지키고자 힘썼다. 

모세는 하나님 앞에는 충성된 종이고 백성들에게는 좋은 리더임을 볼 수 있다. 모세는 지혜롭게 한 민족의 리더로써 대표성을 갖고 여호와께 용서를 구했다. 

특히 하나님과 아브라함과 맺었던 약속을 상기시키면서 하나님의 명예가 실축 될 것을 우려하며 매달리니 일단 여호와께서 심판을 멈추셨다. 

정말 모세 같은 훌륭한 지도자가 되고 싶다. 자신의 이익보다 주님의 명예와 영광을 생각하는 사람, 영혼들의 생명을 지키는 마음, 그리고 죄와 타협하지 않고 결단적인 행동하는 모습이 더욱 값진 모습으로 나타난다. 

그러한 모세를 여호와는 이미 아시고 수백만 명을 이끄는 리더로 선택하신 것 같다. 

9.적용(나):
하나님외에 의지하는 금 송아지를 찾아 불태우고, 오직 주님만 믿고 의존하는 삶을 살아내야겠다.

10. 영적터치 (단어 또는 구절)
20절: 그들이 만든 송아지를 가져다가 불살라 부수어

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-02', '출애굽기', '32장 21절~30절', '아론의 변명과 하나님의 편에 선 백성', '출애굽기 32장
21   모세가 아론에게 이르되 이 백성이 당신에게 어떻게 하였기에 당신이 그들을 큰 죄에 빠지게 하였느냐
22   아론이 이르되 내 주여 노하지 마소서 이 백성의 악함을 당신이 아나이다
23   그들이 내게 말하기를 우리를 위하여 우리를 인도할 신을 만들라 이 모세 곧 우리를 애굽 땅에서 인도하여 낸 사람은 어찌 되었는지 알 수 없노라 하기에
24   내가 그들에게 이르기를 금이 있는 자는 빼내라 한즉 그들이 그것을 내게로 가져왔기로 내가 불에 던졌더니 이 송아지가 나왔나이다
25   모세가 본즉 백성이 방자하니 이는 아론이 그들을 방자하게 하여 원수에게 조롱거리가 되게 하였음이라
26   이에 모세가 진 문에 서서 이르되 누구든지 여호와의 편에 있는 자는 내게로 나아오라 하매 레위 자손이 다 모여 그에게로 가는지라
27   모세가 그들에게 이르되 이스라엘의 하나님 여호와께서 이렇게 말씀하시기를 너희는 각각 허리에 칼을 차고 진 이 문에서 저 문까지 왕래하며 각 사람이 그 형제를, 각 사람이 자기의 친구를, 각 사람이 자기의 이웃을 죽이라 하셨느니라
28   레위 자손이 모세의 말대로 행하매 이 날에 백성 중에 삼천 명 가량이 죽임을 당하니라
29   모세가 이르되 각 사람이 자기의 아들과 자기의 형제를 쳤으니 오늘 여호와께 헌신하게 되었느니라 그가 오늘 너희에게 복을 내리시리라
30   이튿날 모세가 백성에게 이르되 너희가 큰 죄를 범하였도다 내가 이제 여호와께로 올라가노니 혹 너희를 위하여 속죄가 될까 하노라 하고

