2025년 4월 3일 출애굽기 32장 21~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
모세: 21, 23, 25, 26, 27, 28, 29, 30
아론: 21, 22, 25
백성: 21, 22, 25, 28, 30
당신: 21(2), 22
큰 죄: 21, 30
방자: 25(2)
여호와: 26, 27, 29, 30
형제; 27, 29
4.주제 만들기: 아론의 변명과 하나님의 편에 선 백성

5.하나님 찾기(관찰)
- 하나님의 편에 선 자들에게 자기의 형제와 친구와 이웃을 죽이라 명하심

6.인간 찾기(관찰)
- 모세가 아론을 꾸짖음
- 아론이 변명함
- 모세가 하나님의 편에 선 백성을 나오라 말함
- 레위 자손이 다 나왔고, 삼천명 가량을 죽임
- 이튿날 모세가 여호와께 올라겠다 말함
 
7.하나님 찾기(해석)
- 모세가 중보기도를 했음에도 우상을 숭배한 자들을 처단하시는 것을 보면,
- 우상 숭배를 얼마나 미워하시는지 알 수 있다.
- 우상 숭배는 사망의 길이다.

8.인간 찾기(해석)
- 백성을 올바른 길로 인도하지 못하고,
- 우상 숭배를 하게 한 아론은 지도자 모세에게 말도 안 되는 변명을 한다.
- “금 고리를 모아서 불에 넣었더니 금 송아지가 나왔다.”
- 하지만 아론은 분명 송아지 틀을 만들었고 거기에 넣었다.
- 아론은, 그리고 인간은 이렇게 연약한 존재이다.
- 모세는 이런 아론이 그들을 방자하게 하여 원수에게 조롱거리가 되게 하였다고 말한다
- 분명 아론은 백성ㅇ르 올바른 길로 인도할 수 있었다.
- 하나님의 편에 선 레위 지파 모든 사람이 우상 숭배자들을 처단한다
- 이것은 대단한 결심을 한 것인데,
- 처단한 사람들 중에는 가까운 사이도 있었을 것이기 때문이다.
- 모세는 이 행동을 자신을 하나님께 드린 행동이라 말했다.
- 자기를 부인하고 영육혼을 하나님께 산제물로 드리는 행동으로 볼 수도 있을 것이다.

9.적용(나) 
- 내게도 잘못을 저지르고 합리화를 하거나 변명거리를 찾는 모습이 있다.
- 정말로 주의해야 할 부분이다.
- 내 죄를 하나님 앞에 정직하게 드러내고 회개해야 한다.

- 나를 부인하고 날마다 내 십자가를 지고 예수님을 따라야 한다. 
- 하나님 나라와 의를 구하고, 하나님 나라를 전파하시기 위해 이곳저곳을 누비신 예수님을 따라야 한다.

10.영적 터치(단어/구절)
  29   모세가 이르되 각 사람이 자기의 아들과 자기의 형제를 쳤으니 오늘 여호와께 헌신하게 되었느니라 그가 오늘 너희에게 복을 내리시리라

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-03', '출애굽기', '32장 31절~35절', '인간의 죄를 위해 중보한 모세, 인간을 위해 나타나실 예수님', '[출32:31-35]
31 모세가 여호와께로 다시 나아가 여짜오되 슬프도소이다 이 백성이 자기들을 위하여 금 신을 만들었사오니 큰 죄를 범하였나이다
32 그러나 이제 그들의 죄를 사하시옵소서 그렇지 아니하시오면 원하건대 주께서 기록하신 책에서 내 이름을 지워 버려 주옵소서
33 여호와께서 모세에게 이르시되 누구든지 내게 범죄하면 내가 내 책에서 그를 지워 버리리라
34 이제 가서 내가 네게 말한 곳으로 백성을 인도하라 내 사자가 네 앞서 가리라 그러나 내가 보응할 날에는 그들의 죄를 보응하리라
35 여호와께서 백성을 치시니 이는 그들이 아론이 만든 바 그 송아지를 만들었음이더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도
2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 책에서(32,33절)
- 죄(31,32,33,34절)
- 보응(34절)
- 여호와(31,33,35절)
- 모세(31,33절)
- 지워버리다(32,33절)
4. 주제만들기: 인간의 죄를 위해 중보한 모세, 인간을 위해 나타나실 예수님
5. 하나님 찾기 (관찰)
- 하나님은 모세의 기도를 들으시고 누구든지 모세에게 죄를 범하면 생명책에서 지워버리겠다고 말씀하심
- 하나님은 때가 되면 이스라엘 백성에게 징벌하겠다 말씀하심
- 이스라엘 백성에게 전염병을 내리심
6. 인간 찾기 (관찰)
- 모세는 슬퍼하며 하나님께 큰 죄를 범하였다고 말함
- 모세는 하나님께 죄를 사하여 달라고 말하며 그렇지 않으면 하나님께서 기록한 책에서 자신을 지워달라고 말함 
7. 하나님 찾기 (해석)
- 공의의 하나님은 인간의 죄를 가만두지 않으신다. 하나님의 때에 공의를 위한 하나님의 징계는 반드시 이루어진다. 
- 하나님은 중보기도를 들으시고 그 분의 생각을 돌이키시는 분이다. 하나님은 왜 중보기도를 허락하셨을까? 그것은 우리를 너무 사랑하시기 때문일 것이다. 단 한사람의 영혼도 소중히 아끼는 하나님은 모세의 기도를 통해 생명책에서 모세를 지우는 대신 자신이 직접 이 땅에 오셔서 인간의 모든 죄를 짊어지는 선택을 하셨다. 한 영혼도 포기하지 않는 하나님의 사랑을 깨닫는다면 우리는 한 영혼도 포기해서는 안된다. 
8. 인간(해석):
- 모세는 무엇 때문에 슬펐을까? 화가나서 그들을 모두 진멸하라는 말이 먼저 나온 것이 아니라 슬퍼했고, 자신을 대신해 그들을 살려달라는 기도를 했다. 모세는 하나님에 대해 너무 잘 알았던 것 같다. 그 분이 우리를 사랑하시는 것과 그 분을 통해 자신이 누린 것들을 이스라엘 백성 모두가 누리길 진정으로 바랬던 것이다.
9. 적용(나): 
- 한 영혼도 포기하지 말고 끝까지 기도하자
- 누군가에게 중보기도자로 기억되도록 끊기지 않고 기도를 이어가야겠다. 
10. 영적터치(단어/구절)
- 슬프도소이다.
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-04', '출애굽기', '33장 1절~10절', ' ', '(출애굽기 33장)
1.  여호와께서 모세에게 이르시되 너는 네가 애굽 땅에서 인도하여 낸 백성과 함께 여기를 떠나서 내가 아브라함과 이삭과 야곱에게 맹세하여 네 자손에게 주기로 한 그 땅으로 올라가라
2. 내가 사자를 너보다 앞서 보내어 가나안 사람과 아모리 사람과 헷 사람과 브리스 사람과 히위 사람과 여부스 사람을 쫓아내고
3. 너희를 젖과 꿀이 흐르는 땅에 이르게 하려니와 나는 너희와 함께 올라가지 아니하리니 너희는 목이 곧은 백성인즉 내가 길에서 너희를 진멸할까 염려함이니라 하시니
4. 백성이 이 준엄한 말씀을 듣고 슬퍼하여 한 사람도 자기의 몸을 단장하지 아니하니
5. 여호와께서 모세에게 이르시기를 이스라엘 자손에게 이르라 너희는 목이 곧은 백성인즉 내가 한 순간이라도 너희 가운데에 이르면 너희를 진멸하리니 너희는 장신구를 떼어 내라 그리하면 내가 너희에게 어떻게 할 것인지 정하겠노라 하셨음이라
6. 이스라엘 자손이 호렙 산에서부터 그들의 장신구를 떼어 내니라
7.  모세가 항상 장막을 취하여 진 밖에 쳐서 진과 멀리 떠나게 하고 회막이라 이름하니 여호와를 앙모하는 자는 다 진 바깥 회막으로 나아가며
8. 모세가 회막으로 나아갈 때에는 백성이 다 일어나 자기 장막 문에 서서 모세가 회막에 들어가기까지 바라보며
9. 모세가 회막에 들어갈 때에 구름 기둥이 내려 회막 문에 서며 여호와께서 모세와 말씀하시니
10. 모든 백성이 회막 문에 구름 기둥이 서 있는 것을 보고 다 일어나 각기 장막 문에 서서 예배하며

