1:감동받는 단어나 구절 찾기(영적터치)

2025년 4월5일 
출애굽기 33장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
회막: 8절(2) 9절(2) 10절
함께: 1절 3절
구름 기둥: 9절 10절
진멸: 3절 5절

4.주제 만들기: 
회막

5.하나님 찾기 (관찰)
진노하시는 여호와.
(목이 곧은 이스라엘 백성을 진멸할까 염려하시는 여호와)
구름 기둥을 보내주신 여호와

6.인간 찾기(관찰)
장신구를 떼어 내는 이스라엘 자손들
회막 문에 서서 여호와께 예배하는 이스라엘 백성.

7.하나님 찾기(해석)
''회막''은 성소와 다른 장소이며 성소를 짓기 전 임시방편으로 지어진 영적 장소라고 여겨진다. 이 장소가 갖는 남다른 의미가 있다고 생각된다.

 완전한 성막이 아니더라도 하나님은 진심으로 여호와를 찾는 사람들을 만나 주신다. 실제로 이곳에서 모세는 하나님과의 영적 교제를 한 것을 알 수 있다. 

하나님과의 대화할 수 있는 장소로 매우 소중하다는 생각이 든다. 문제 해결을 할 수 있는 장소이다. 

하나님은 금송아지 사건으로 말미암아 진노가 아직 완전히 풀리지 않은 상황에서 젖과 꿀이 흐르는 가나안 땅에 사자를 먼저 보내질지언정 자신은 함께 가지 않겠다고 하셨었다. 

이유는 이스라엘 백성이 너무 목이 곧았기 때문이라 말씀하신다. 그러나 모세는 회막의 장소에서 하나님과 영적 대화를 나누어 문제를 해결한 듯하다.


10절에 이스라엘 백성에게 구름 기둥을 세워주신 것을 보면 계속적으로 함께하심의 상징을 간접적으로 느낄 수 있다. 
 
8. 인간 찾기(해석)
위기 때 리더의 역할의 중요성을 본다. 현대에서도 마찬가지로 때때로 화려한 장소가 아닌 골방이라도 진심으로 주님께 매달리면 모든 문제를 해결하는 방법을 주님께서는 제시해 주실 것을 확신한다.

9.적용(나):
어떠한 장소에서도 늘 주님과 영적 대화 즉 기도를 더욱 열심히 해야겠다.

10. 영적터치 (단어 또는 구절)
7절: 회막

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-05', '출애굽기', '33장 11절~23절', ' ', '(출애굽기 33장)
11. 사람이 자기의 친구와 이야기함 같이 여호와께서는 모세와 대면하여 말씀하시며 모세는 진으로 돌아오나 눈의 아들 젊은 수종자 여호수아는 회막을 떠나지 아니하니라
12.  모세가 여호와께 아뢰되 보시옵소서 주께서 내게 이 백성을 인도하여 올라가라 하시면서 나와 함께 보낼 자를 내게 지시하지 아니하시나이다 주께서 전에 말씀하시기를 나는 이름으로도 너를 알고 너도 내 앞에 은총을 입었다 하셨사온즉
13. 내가 참으로 주의 목전에 은총을 입었사오면 원하건대 주의 길을 내게 보이사 내게 주를 알리시고 나로 주의 목전에 은총을 입게 하시며 이 족속을 주의 백성으로 여기소서
14. 여호와께서 이르시되 내가 친히 가리라 내가 너를 쉬게 하리라
15. 모세가 여호와께 아뢰되 주께서 친히 가지 아니하시려거든 우리를 이 곳에서 올려 보내지 마옵소서
16. 나와 주의 백성이 주의 목전에 은총 입은 줄을 무엇으로 알리이까 주께서 우리와 함께 행하심으로 나와 주의 백성을 천하 만민 중에 구별하심이 아니니이까
17. 여호와께서 모세에게 이르시되 네가 말하는 이 일도 내가 하리니 너는 내 목전에 은총을 입었고 내가 이름으로도 너를 앎이니라
18. 모세가 이르되 원하건대 주의 영광을 내게 보이소서
19. 여호와께서 이르시되 내가 내 모든 선한 것을 네 앞으로 지나가게 하고 여호와의 이름을 네 앞에 선포하리라 나는 은혜 베풀 자에게 은혜를 베풀고 긍휼히 여길 자에게 긍휼을 베푸느니라
20. 또 이르시되 네가 내 얼굴을 보지 못하리니 나를 보고 살 자가 없음이니라
21. 여호와께서 또 이르시기를 보라 내 곁에 한 장소가 있으니 너는 그 반석 위에 서라
22. 내 영광이 지나갈 때에 내가 너를 반석 틈에 두고 내가 지나도록 내 손으로 너를 덮었다가
23. 손을 거두리니 네가 내 등을 볼 것이요 얼굴은 보지 못하리라

