3.반복단어 찾기(형광펜 사용 추천)
은총: 12절 13절(2) 17절
원하건데: 13절 18절
주의 목전: 13절 16절 17절
은혜 베풀: 19절(2)
친히 가리라: 14절 15절

4.주제 만들기: 
친히 가리라 하신 여호와 

5.하나님 찾기 (관찰)
친히 가리라 하신 여호와 
모세의 간절한 메달림에 받아 주시는 여호와.

6.인간 찾기(관찰)
여호와께 간절하게  메달림으로 허락을 받은 모세(여호와께 동행하싱)
여호와 와 대면하는 모세.

7.하나님 찾기(해석)
하나님은 모세의 응석을 받아주시고 다시 함께하기로 자비를 베푸셨다 

하나님은 순순한 동기를 가지고 다가오는 자녀를 외면하지 않으시는 것 같다.
 
8. 인간 찾기(해석)
모세는 누구보다 여호와의 심중을 깊이 아는 사람 같다. 이스라엘 백성의 잘못된 행동의 반응으로 여호와는 그들과 함께 가나안 땅으로 가시기를 원치 않으셨다. 


그런데도 모세는 여호와 동행 없이 가기를 원치 않았다. 모세는 알고 있었다. 하나님의 함께하심 없이는 목적지까지 제대로 갈 수 없다는 것을. 

모세는 지혜롭게 변명한다. 과거에 자신이 받았던 은총을 되새기면서 하나님께 함께 가기를 때에 쓴다. 

결국 하나님은 모세의 말을 수용하신다. 이러한 장면을 보면 아버지에게 응석 부리는 마치 아기 같은 느낌을 받는다. 

하나님의 자녀들도 삶에서 실수로 잘못을 저질렀더라도 여호와를 피하지 말고 솔직히 잘못을 시인하고 용서를 구하며 주님께 매달리는 태도를 보이는 것이 지혜롭고 현명한 태도인 것 같다.

9.적용(나):
늘 하나님과 동행하는 삶을 살도록 힘써야겠다.

10. 영적터치 (단어 또는 구절)
17절: 네가 말하는 이 일도 내가 하리니 너는 내 목전에 은총을 입었고 내가 이름으로도 너를 앎이니라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-06', '출애굽기', '34장 1절~10절', '자비롭고, 은혜롭고, 인자와 진실이 많으신 하나님', '[출34:1-10]
1 여호와께서 모세에게 이르시되 너는 돌판 둘을 처음 것과 같이 다듬어 만들라 네가 깨뜨린 처음 판에 있던 말을 내가 그 판에 쓰리니
2 아침까지 준비하고 아침에 시내 산에 올라와 산 꼭대기에서 내게 보이되
3 아무도 너와 함께 오르지 말며 온 산에 아무도 나타나지 못하게 하고 양과 소도 산 앞에서 먹지 못하게 하라
4 모세가 돌판 둘을 처음 것과 같이 깎아 만들고 아침에 일찍이 일어나 그 두 돌판을 손에 들고 여호와의 명령대로 시내 산에 올라가니
5 여호와께서 구름 가운데에 강림하사 그와 함께 거기 서서 여호와의 이름을 선포하실새
6 여호와께서 그의 앞으로 지나시며 선포하시되 여호와라 여호와라 자비롭고 은혜롭고 노하기를 더디하고 인자와 진실이 많은 하나님이라
7 인자를 천대까지 베풀며 악과 과실과 죄를 용서하리라 그러나 벌을 면제하지는 아니하고 아버지의 악행을 자손 삼사 대까지 보응하리라
8 모세가 급히 땅에 엎드려 경배하며
9 이르되 주여 내가 주께 은총을 입었거든 원하건대 주는 우리와 동행하옵소서 이는 목이 뻣뻣한 백성이니이다 우리의 악과 죄를 사하시고 우리를 주의 기업으로 삼으소서
10 여호와께서 이르시되 보라 내가 언약을 세우나니 곧 내가 아직 온 땅 아무 국민에게도 행하지 아니한 이적을 너희 전체 백성 앞에 행할 것이라 네가 머무는 나라 백성이 다 여호와의 행하심을 보리니 내가 너를 위하여 행할 일이 두려운 것임이니라

