- 모세(1,4,8절)
- 돌판(1,4절)
- 처음과 같이(1,4절)
- 백성(9,10절)
4. 주제만들기: 자비롭고, 은혜롭고, 인자와 진실이 많으신 하나님
5. 하나님 찾기 (관찰)
- 모세에게 돌판을 처음과 같이 다듬고 시내산으로 올라오라 명하시는 하나님
- 구름 가운데 강림하시고 모세와 함께 서서 여호와의 이름을 선포하심
- 자비롭고 은혜롭고 노하기를 더디하시고 인자와 진실이 많으시며 인자를 천대까지 베푸시과 죄와 악을 용서하시는 하나님
- 그러나 벌을 면제하지는 아니하시고 악행을 삼대까지 보응하시는 하나님
- 모세의 요청을 듣고 언약을 세우시는 하나님
6. 인간 찾기 (관찰)
- 모세는 엎드려 경배하며 이스라엘 백성과 동행 해달라 요청하고 목이 뻣뻣한 백성의 죄를 사하시고 기업이 되게 해달라고 요청함
7. 하나님 찾기 (해석) 
- 자비와 긍휼이 넘치시는 하나님은 죄와 악을 용서하시는 분이시다. 그러나 죄에 대한 벌은 보응하신다. 우리는 죄를 지을 수 있는 연약한 존재이다. 그러나 죄를 깨닫고 용서를 구하면 너그럽고 인자하신 하나님은 우리의 죄를 용서하신다. 
- 나의 죄로 인해 어려운 상황에 처해있을 때 그것을 해결해달라는 기도를 하곤 한다. 하나님은 나의 죄는 용서하시지만 나의 죄로 인한 상황을 해결하였을 때 과연 나는 죄에서 돌이킬 수 있을까? 나에게 유익한 것은 상황의 정리, 해결이 아닌 완전히 돌이키고 깨달아 하나님을 의지할 수 있는 환경일 것이다.
8. 인간(해석):
- 모세는 하나님의 명령에 돌판을 처음과 같이 만들었다. 얼마나 정성을 다했을까? 처음과 같이 다시 만들어야 했음에도 모세는 최선을 다했다. 나에게도 그러한 마음이 필요할 것이다.
- 모세는 하나님의 거룩하심을 직접 보고 즉시 엎드려 경배했다. 그럼에도 자신의 요청을 담대히 드렸다. 모세는 하나님을 너무 잘 알았다. 그리고 자신의 소명도 알고 있었다. 반드시 이스라엘 백성을 가나안 땅으로 이끌어야할 소명을 알기에, 죄 많은 이스라엘 백성을 하나님께 요청하여 용서해주길 간구했다. 
9. 적용(나): 
- 모세와 같은 마음으로 노방전도를 하고 싶다. 내 안에 사랑의 마음이 가득 임하길 소망한다.
10. 영적터치(단어/구절)
- 처음과 같이
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-07', '출애굽기', '34장 11절~20절', '하나님의 명령', '출애굽기 34장
11   너는 내가 오늘 네게 명령하는 것을 삼가 지키라 보라 내가 네 앞에서 아모리 사람과 가나안 사람과 헷 사람과 브리스 사람과 히위 사람과 여부스 사람을 쫓아내리니
12   너는 스스로 삼가 네가 들어가는 땅의 주민과 언약을 세우지 말라 그것이 너희에게 올무가 될까 하노라
13   너희는 도리어 그들의 제단들을 헐고 그들의 주상을 깨뜨리고 그들의 아세라 상을 찍을지어다
14   너는 다른 신에게 절하지 말라 여호와는 질투라 이름하는 질투의 하나님임이니라
15   너는 삼가 그 땅의 주민과 언약을 세우지 말지니 이는 그들이 모든 신을 음란하게 섬기며 그들의 신들에게 제물을 드리고 너를 청하면 네가 그 제물을 먹을까 함이며
16   또 네가 그들의 딸들을 네 아들들의 아내로 삼음으로 그들의 딸들이 그들의 신들을 음란하게 섬기며 네 아들에게 그들의 신들을 음란하게 섬기게 할까 함이니라
17   너는 신상들을 부어 만들지 말지니라
18   너는 무교절을 지키되 내가 네게 명령한 대로 아빕월 그 절기에 이레 동안 무교병을 먹으라 이는 네가 아빕월에 애굽에서 나왔음이니라
19   모든 첫 태생은 다 내 것이며 네 가축의 모든 처음 난 수컷인 소와 양도 다 그러하며
20   나귀의 첫 새끼는 어린 양으로 대속할 것이요 그렇게 하지 아니하려면 그 목을 꺾을 것이며 네 아들 중 장자는 다 대속할지며 빈 손으로 내 얼굴을 보지 말지니라

