INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-08', '출애굽기', '34장 21절~30절', ' ', '(출애굽기 34장)
21. 너는 엿새 동안 일하고 일곱째 날에는 쉴지니 밭 갈 때에나 거둘 때에도 쉴지며
