4.주제 만들기: 
다시 언약을 세우시는 여호와.

5.하나님 찾기 (관찰)
각종 절기(수장절, 칠칠절,무교절)를 지키라 말씀 하시는 여호와.
언약의 말씀 곧 십계명을 돌반들에 기록하신 여호와.

6.인간 찾기(관찰)
40일을 다시 단식하는 모세.
단식 후 얼굴에 영적 광채가 나는 모세.
십계명 돌판을 시내산에서 들고 내려오는 모세.
그러한 모세의 얼굴을 보고 두려워하는 백성들.

7.하나님 찾기(해석)
하나님은 다양한 절기를 그의 백성들에게 주심으로 그들이 더욱 경건해지고 여호와와 깊은 교제를 원하심을 볼 수 있다. 

특히 칠칠절(맥추절,오순절)이나 수장절(장막절,초막절)의 봄이나 가을의 추수 시기의 절기를 통하여 모든 자연의 주인이 하나님이신 것을 알게 하신 것 같다.


23절에 "모든 남자는 매년 세 번씩 주 여호와 이스라엘의 하나님 앞에 보일지라" 기록된 것을 보면 무교절 오순절 장막절을 더욱 지키라고 하신 것 같다.


28절에 모세가 사십일 사십 야를 단식하면서 돌판에 십계명을 받았다.


과거 40일 단식하면서 받은 십계명 돌판이 죄로 인하여 깨지고 다시 40일 단식하면서 받는 새로운 돌판을 생각할 때 죄를 짓고 용서받고 다시 회복하는 것이 얼마나 힘든 일인지 짐작이 간다. 

그런데도 하나님은 육체적으로 지쳐있는 모세에게 다른 사람들이 두려워할 만한 얼굴 피부에 광채가 나게 하셨다. 

하나님께 온전히 붙잡힌 사명자는 언제나 빛나는 인생을 사는 사람인 것이 확실하다.
 
8. 인간 찾기(해석)

9.적용(나):
하나님이 주신 말씀을 소중히 여기고 그대로 순종하는 삶을 살도록 힘써야겠다.

