6.인간 찾기(관찰)
- 모세가 아론과 회중을 부름
- 아론과 회중의 어른이 모세에게 나옴
- 모세가 그들에게 말하자 그제서야 이스라엘 자손이 모세 앞으로 나옴
- 모세가 하나님의 명령을 회중에게 전함
- 모세가 회중 앞에서는 수건으로 얼굴을 가리고
- 하나님 앞에서는 수건을 벗음

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 하나님의 영광이 모세에게 비춰지고,
- 40일 동안 하나님과 친밀한 교제를 나눈 모세에게 
- 하나님의 영광의 광채가 임하였다.
- 백성들은 하나님의 영광이 비춰진 모세가 두려웠다.

- 모세는 겸손하여 이스라엘 자손들이 그 얼굴의 빛을 보지 못하도록 가리었다.
- 모세는 얼굴에서 빛이 나는 것을 자랑하려 하지 않았다.
- 그것을 권력으로 사용하려 하지 않았다.
- 모세는 참으로 겸손하고 온유한 자다.

- 하나님과 친밀히 교제하는 자에게는 하나님의 영광이 임한다는 것을 알 수 있다.
- 하나님의 영광이 임했을 때, 성령 충만할 때, 
- 교만하지 않고 겸손히 이웃을 섬기는 자가 돼야 한다.

- 하나님의 영광은 내 능력으로 나타난 것이 아니라,
- 하나님의 능력으로 나타난 것이므로 자랑해서는 안 된다. 

9.적용(나) 
- 능력이 조금 나타나면 기뻐할 때가 있다.
- 기뻐하고 끝나야 하는데, 교만에 빠져버릴 때가 있다.
- 능력도 성령 충만도 하나님께서 주신 것이므로 자랑치 않아야 한다.
- 그저 감사하며, 겸손하게 맡겨진 사명을 감당해야 한다. 

