7. 하나님 찾기 (해석) 
- 오늘 말씀에서 규율과 자유를 모두 허락하시는 하나님을 볼 수 있다. 
- 하나님께선 안식일을 거룩한 날로 엄숙히 지켜야하는 날임을 알려주셨다. 안식일에 일을 할 경우 죽음에 이를 정도로 안식일을 반드시 지켜야할 날로 이스라엘 백성에게 강조하셨다. 
- 인간은 매일 거룩한 삶을 살 수 없다. 그러므로 하나님께서 하루 동안 완전한 집중, 완전한 예배, 하나님과의 완전한 동행을 이루도록 특별히 지정한 날이다. 오늘의 우리는(나는) 안식익을 거룩히, 엄숙히 지키고 있을까?
- 두 번째로는 자유를 허락하셨다. 하나님께선 예배에 필요한 것을 자유롭게 자신이 가진 소유 중 택하여 드리도록 하셨다. 가진 것이 많은자나, 적은자나 하나님은 마음의 중심을 보시는 분이다. 자신이 가진 것을 온전히 하나님께 드릴 수 있는 믿음이 중요하다. 나는 하나님께 온전히 나의 것을 내어드릴 수 있을까?

8. 인간(해석):

9. 적용(나): 
- 주일 예배의 거룩함과 엄숙함을 잊은채 형식적인 신앙 생활을 회개하며 예배를 사모하고, 하나님께 영광 올리는 귀한 시간이 되도록 기도해야겠다.
- 나의 재물은 나의 것이 아니다. 하나님은 나에게 필요 이상의 것을 요구하지도 않으신다. 내 수준에 맞는 구제 활동을 이어갈 수 있도록 기도해야겠다.
