4.주제 만들기: 
여호와께 드릴 것들

5.하나님 찾기 (관찰)
성소에 들어갈 필요한 용품들을 제작하라 명령하시는 여호와.

6.인간 찾기(관찰)

7.하나님 찾기(해석)
하나님은 이스라엘 백성들에게 성막과 그 안에 들어갈 기구나 덮게 또는 진설병, 등잔대 등 다양한 필요 용품을 제작하라고 명령하셨다. 

그리고 제사장의 옷까지도 주문하셨다. 성막 관련 주문하신 하나님을 생각할 때 얼마나 섬세하시고 전능하신지 충분히 가늠이 간다. 

성막을 천국의 작은 모형이라고 생각한다면 실제적인 천국은 어떨까? 너무 기대된다. 

이렇게 모든 것을 완벽하게 준비하시어 인간들과 함께 연합하기를 바라신다. 

이러한 것을 생각할 때 내가 스스로 노력해서 새로운 성막을 만들어 만족하며 살라고 노력했던 경우는 없었는가를 뒤돌아본다. 

이미 모든 것을 완벽하게 준비하시고 지구를 주셨는데…. 그것을 충분히 누리고 산다는 것이 복된 삶인 것 같다. 

하나님 명령에 늘 순종하며 그분 은혜의 장막에 머무는 것은 매우 지혜로운 사람인 것 같다.
 
8. 인간 찾기(해석)

9.적용(나):
하나님의 명령에 늘 그대로 따르는 청지기가 되도록 노력해야겠다.

10. 영적터치 (단어 또는 구절)
