5.하나님 찾기 (관찰)
거룩하신 여호와.
지명하여 부르시는 여호와.

6.인간 찾기(관찰)
기쁜 마음으로 여호와께 자신의 예물을 드리는 이스라엘 백성.

7.하나님 찾기(해석)
자신의 소중한 물건들을 아낌없이 하나님이 원하시는 성막이나 그 안에 사용 받기를 위하여 이스라엘 백성들은 헌납하였다. 

실제로 여호와께 직접 드린다고 생각해도 틀리지 않을 것이다. 

드리는 사람들의 마음은 자원하는 마음이었고 기쁜 마음으로 헌물 하였다. 

중심을 보시는 하나님 또한 분명 기뻐하셨을 것이다. 

우주 만물을 창조하신 모든 물질의 주인이신 하나님이 초라하게 긴 노예 생활을 겨우 청산하고 광야 길을 가는 가난한 백성들의 귀중품을 받는 것을 진정한 부자이신 하나님이 원하셨을까? 

마치 대기업 회장이 5살 정도가 되는 손주의 코 묻은 돈을 원한다고 누구도 그렇게 생각하지 않을  것이다. 

그러나 손주가 만약 기쁜 마음으로 할아버지 아이스크림 사서 먹으라고 자원하는 마음으로 준다면 그 할아버지 회장은 크게 기뻐할 것이다. 

물질보다도 누군가가 나를 사랑한다는 사실 때문일 것이다. 더군다나 혈육이기 때문에 더 그럴 것 같다. 

하나님도 마찬가지로 진심으로 감사하는 마음으로 주님을 위하여 헌신하고 믿고 따르는 자녀라면 더욱 기억하사 함께하실 것 같다. 

8. 인간 찾기(해석)

9.적용(나):
늘 자원하는 기쁜 마음으로 주님이 주신  사명을 잘 감당해야겠다.

