INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-13', '출애굽기', '35장 31절~35절', '하나님의 영으로 일하게 하시는 하나님', '[출35:31-35]
31 하나님의 영을 그에게 충만하게 하여 지혜와 총명과 지식으로 여러 가지 일을 하게 하시되
32 금과 은과 놋으로 제작하는 기술을 고안하게 하시며
33 보석을 깎아 물리며 나무를 새기는 여러 가지 정교한 일을 하게 하셨고
34 또 그와 단 지파 아히사막의 아들 오홀리압을 감동시키사 가르치게 하시며
35 지혜로운 마음을 그들에게 충만하게 하사 여러 가지 일을 하게 하시되 조각하는 일과 세공하는 일과 청색 자색 홍색 실과 가는 베 실로 수 놓는 일과 짜는 일과 그 외에 여러 가지 일을 하게 하시고 정교한 일을 고안하게 하셨느니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도
2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 지혜(31,35절) 
- 일을 하게 하시고(31,33,35절)
- 일(31,33,35절)
- 정교한(33,35절)

4. 주제만들기: 하나님의 영으로 일하게 하시는 하나님

5. 하나님 찾기 (관찰)
- 하나님의 영을 충만하게 하고 총명과 지식으로 정교한 일을 하게 하시는 하나님

6. 인간 찾기 (관찰)
- 유다 지파 훌의 손자 우리의 아들 브살렐은 금과 은과 놋으로 제작하는 기술을 고안하고 보석을 깎아 나무를 새기는 정교한 일을 함
- 단 지파 아히사막의 아들 오홀리압은 가르치는 일과, 조각하는 일, 세공하는 일, 실로 수 놓는 일과 짜는 일 등 정교한 일을 고안하게 함

7. 하나님 찾기 (해석) 
- 하나님의 영이 충만한 사람은 하나님 나라를 볼 수 있다. 
- 하나님의 뜻을 아는 것 뿐만 아니라 지혜와 총명과 지식이 가득하여 하나님께서 원하시는 것을 이룰 수 있는 능력을 주신다. 
- 우리는 하나님의 영으로 충만하여 하나님의 나라와 그 분의 일을 완벽히 수행할 수 있는 능력을 갖추어야 할 것이다.
- 하나님은 본인의 의지로 선택하여 하나님의 영을 부어주신다. 마치 우리가 예수님을 믿고 하나님을 믿게 된 것은 하나님의 은혜처럼 하나님의 영도 하나님께서 은혜로 부어주시는 것이다. 하나님께서 부어주신 영을 지혜롭고 총명하게 활용하는 것이 중요하다.
8. 인간(해석):
- 하나님의 영으로 지혜와 총명을 힘에 입은 인간은 정교한 일과 가르치는 일을 지혜롭게 해결한다. 이것은 인간의 고유한 능력이 아니라 하나님으로부터 나왔다는 것을 잊지 말아야 한다.
- 나의 나 된 것은 모두 하나님의 은혜다. 그 분께서 내게 부어주신 성령의 은혜를 통해 지혜롭고 총명하게 그 분이 이루어야할 일을 정교하게 완수하여야 한다.
9. 적용(나): 
- 모든 것은 하나님의 은혜이다. 교만하지 말고 하나님께 감사하며 그분의 뜻을 이루어가는 사람이 되어야겠다.
- 영적 전쟁에서 승리하도록 몸부림치며 기도하며 간구해야겠다.
10. 영적터치(단어/구절)
- 하나님의 영
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-14', '출애굽기', '36장 1절~10절', '명령하신 대로', '출애굽기 36장
1 브살렐과 오홀리압과 및 마음이 지혜로운 사람 곧 여호와께서 지혜와 총명을 부으사 성소에 쓸 모든 일을 할 줄 알게 하신 자들은 모두 여호와께서 명령하신 대로 할 것이니라
2 모세가 브살렐과 오홀리압과 및 마음이 지혜로운 사람 곧 그 마음에 여호와께로부터 지혜를 얻고 와서 그 일을 하려고 마음에 원하는 모든 자를 부르매
3 그들이 이스라엘 자손의 성소의 모든 것을 만들기 위하여 가져온 예물을 모세에게서 받으니라 그러나 백성이 아침마다 자원하는 예물을 연하여 가져왔으므로
4 성소의 모든 일을 하는 지혜로운 자들이 각기 하는 일을 중지하고 와서
5 모세에게 말하여 이르되 백성이 너무 많이 가져오므로 여호와께서 명령하신 일에 쓰기에 남음이 있나이다
6 모세가 명령을 내리매 그들이 진중에 공포하여 이르되 남녀를 막론하고 성소에 드릴 예물을 다시 만들지 말라 하매 백성이 가져오기를 그치니
7 있는 재료가 모든 일을 하기에 넉넉하여 남음이 있었더라
8 일하는 사람 중에 마음이 지혜로운 모든 사람이 열 폭 휘장으로 성막을 지었으니 곧 가늘게 꼰 베 실과 청색 자색 홍색 실로 그룹들을 무늬 놓아 짜서 지은 것이라
9 매 폭의 길이는 스물여덟 규빗, 너비는 네 규빗으로 각 폭의 장단을 같게 하여
10 그 다섯 폭을 서로 연결하며 또 그 다섯 폭을 서로 연결하고

