6. 인간 찾기 (관찰)
- 마음이 지혜로운 자들은 여호와께서 명령하신 대로 할 것
- 모세가 여호와께서 지혜를 부어주시고 그 일을 하려고 마음에 원하는 모든 자를 부름
- 성소를 짓기 위해 백성들이 예물을 가져옴
- 가져온 예물이 쓰고 남음이 있음
- 그만 가져오도록 조치함
- 지혜로운 사람이 성막을 지음

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 하나님께 지혜를 받은 자라도 하나님의 명령대로 성소를 지어야한다.
- 자기 생각에 아름답고 귀하게 만드는 것이 아니라 하나님의 명령 대로 해야한다.
- 하나님께 지혜를 받고 마음에 원하는 자를 불렀다.
- 능력을 받았으나 주님의 일을 거절하는 사람은 하나님이 쓰지 않으신다.
- 은사를 받았다면, 그 은사를 하나님 나라 확장에 쓰고자 노력함이 마땅할 것이다.
- 쓰임 받음에 감사하며.
- 백성들이 하나님의 임재를 두려워하며 사모하였으므로,
- 임재하실 성소를 위해 예물을 넘치게 가져옴
- 지혜를 얻은 자들이 예물을 그만 가져오길 모세에게 요청함
- 모세가 그만 가져올 것을 명함
- 모세는 물질에 대한 욕심이 없음
- 지혜로운 자들이 성막을 짓되 자기들의 지혜로 하지 않고,
하나님께서 주신 설계 대로 성막을 제작함

9. 적용(나): 
- 받은 은사를 하나님 나라 확장을 위해 성실히 사용해야 한다.

10. 영적터치(단어/구절)
- 1절 ...여호와께서 지혜와 총명을 부으사 성소에 쓸 모든 일을 할 줄 알게 하신 자들은 모두 여호와께서 명령하신 대로 할 것이니라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-15', '출애굽기', '36장 11절~20절', ' ', '(출애굽기 36장)
11. 연결할 끝폭 가에 청색 고를 만들며 다른 연결할 끝폭 가에도 고를 만들되
12. 그 연결할 한 폭에 고리 쉰 개를 달고 다른 연결할 한 폭의 가에도 고리 쉰 개를 달아 그 고들이 서로 대하게 하고
13. 금 갈고리 쉰 개를 만들어 그 갈고리로 두 휘장을 연결하여 한 막을 이루었더라
14. 그 성막을 덮는 막 곧 휘장을 염소 털로 만들되 열한 폭을 만들었으니
15. 각 폭의 길이는 서른 규빗, 너비는 네 규빗으로 열한 폭의 장단을 같게 하여
16. 그 휘장 다섯 폭을 서로 연결하며 또 여섯 폭을 서로 연결하고
17. 휘장을 연결할 끝폭 가에 고리 쉰 개를 달며 다른 연결할 끝폭 가에도 고리 쉰 개를 달고
18. 놋 갈고리 쉰 개를 만들어 그 휘장을 연결하여 한 막이 되게 하고
19. 붉은 물 들인 숫양의 가죽으로 막의 덮개를 만들고 해달의 가죽으로 그 윗덮개를 만들었더라
20. 그가 또 조각목으로 성막에 세울 널판들을 만들었으니

