연결 할 휘장

5.하나님 찾기 (관찰)
성막과 휘장을 설계하시고 지시하시는 여호와.

6.인간 찾기(관찰)

7.하나님 찾기(해석)
촘촘하게 성막의 휘장을 하나님은 설계하셨다. 

덥게는 염소의 털과 붉은 물 들인 숫양의 가죽 그리고 해달의 가죽을 사용하라 하셨다. 한 폭에 50개의 고리를 달게 하셨다. 

하나님이 얼마나 성막뿐만 아니라 휘장을 섬세하게 심혈을 기울이고 있는지 알 수 있다. 

특히 휘장을 설계할 때 붉은색을 담은 숫양의 가죽을 사용케 하신 것은 예수님을 연상케 된다. 

예수님이 십자가에서 희생양으로 돌아가실 때 하늘의 휘장이 찢어졌다고 기록된 것을 생각해 본다. 

미래를 미리 아시는 하나님은 이미 자신의 사랑하는 독생자를 희생물로 염두에 두며 준비했을 것이다. 

그러한 넓은 하나님의 마음도 모르고 백성들은 먹는 것 마실 것이 조금 부족하면 불평하는 것 보면 나의 모습을 보는 것 같다. 

이토록 크신 하나님의 사랑을 생각할 때 큰 감동과 삶의 기쁨이 오는 그것 같다.

8. 인간 찾기(해석)

9.적용(나):
예수님은 우리 구원을 위하여 스스로 그의 몸인 휘장이 찢어지는 고통을 겪으셨다. 얼마나 죄송하고 감사한 일 인지 모르겠다. 

특별이 지금은 고난주간이다.   주님의 십자가 고통을 묵상하며 더욱 감사한 마음을 가져야겠다.

