24   그 스무 개 널판 밑에 은 받침 마흔 개를 만들었으되 곧 이 널판 밑에도 두 받침이 그 두 촉을 받게 하였고 저 널판 밑에도 두 받침이 그 두 촉을 받게 하였으며
