- 하나님은 성막을 정교하고, 거룩하고, 아름답게 건축하셨다. 특히 성막을 거룩한 곳, 하나님께서 임재하시는 곳으로 인간이 쉽게 들어올 수 없는 곳임을 드러내셨다. 성막, 성전은 하늘 나라를 나타냄과 동시에 하나님 그 자체 인 것이다.
- 왜 하나님께선 성막을 만드셨을까? 그것은 우리를 향한 하나님의 구속 사역을 나타내고자 하셨기 때문이다. 우리는 예수님이 이 땅에 오시고, 십자가에 달리신 후에야 하나님의 구속 사역을 깨달았지만, 그것도 완벽히 깨닫지 못하고 있지만... 이미 하나님은 인간을 창조하시기 전에 계획하셨다. 어리석은 우리가 깨달을 수 있도록 친히 증거를 남겨주신 것이다.
