5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
하나님의 지시대로 상과 등잔대를 만든 백성들.


7.하나님 찾기(해석)
하나님은 모세를 통하여 이스라엘 백성들에게 진설 병을 올릴 상을 만들 것을 주문하였었다. 말씀을 받은 그들은 그대로 준행하였다. 

상을 만든 목적은 진설 병 12개를 올리는 용도 때문이라 생각할 때 12개는 이스라엘 백성의 12지파를 의미함으로 곧 구별된 거룩한 이스라엘 백성을 의미한다 볼 수 있다.


성막 안에서 주의 백성들이 하나님께 드려질 때 중간에서 돕는 역할을 하는 분은 우리 예수님이심을 알게 된다. 

예수님은 마치 ‘상’ 같은 존재이다. 죄인이 된 우리를 위하여 자신의 보혈로 구분된 백성으로 삼으사 거룩한 하나님께 올려드리는 우리를 붙잡는 역할을 하시기 때문이다. 

12절에 ''그 주위에 손바닥 넓이만 한 턱을 만들고'' 기록된 것을 생각할 때 주님한테서 떨어질 수 없게 영적 안전장치 또는 보호 구간을 만드심을 알 수 있다

우리는 언제나 넘어질 수 있는 존재인 것을 아시어서 주님이 늘 보호해 주시를 느낀다.

13절에 상을 옮길 때 사용할 고리 넷을 보면 주님은 철저히 연합의 원리도 보여주고 있다.

8. 인간 찾기(해석)

9.적용(나):
