26 제단 상면과 전후 좌우면과 그 뿔을 순금으로 싸고 주위에 금 테를 둘렀고
27 그 테 아래 양쪽에 금 고리 둘을 만들었으되 곧 그 양쪽에 만들어 제단을 메는 채를 꿰게 하였으며
28 조각목으로 그 채를 만들어 금으로 쌌으며
29 거룩한 관유와 향품으로 정결한 향을 만들었으되 향을 만드는 법대로 하였더라

