5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 브살렐이 하나님의 말씀대로 번제단과 물두멍, 울타리를 제작했다
- 물두멍에 쓰인 놋은 회막 문에서 수종드는 여인들의 거울로 만들었다

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 하나님의 영에 감동되어, 하나님을 예배할 번제단과 제물을 씻을 물두멍을 제작한 브살렐은
- 하나님의 임재와 영광을 떠올리며 정성스레 만들었을 것이다.
- 너무나 감사하여 때로는 눈물을 흘리며, 늘 찬양하며 만들었을 것이다.

- 물두멍에 쓰인 놋은 여인들이 바친 놋거울을 녹여 만든 것이다.
- 이 시대에 놋거울은 굉장히 귀한 물건이었을 것이다.
- 이 여인들의 하나님을 향한 마음과 물질의 헌신이 상당히 큰 것이었음을 유추할 수 있다.
- 자기를 치장하는데 쓰이는 귀한 놋거울을 바친 것은 자기를 부인하는 하나의 방편이 되었을 것이다. 

9.적용(나)
- 하나님의 임재를 기대하며, 바라며 간절히 기도하는 삶을 살아야 한다.
- 보내신 곳에서 날마다 예배하며 주님의 임재를 바라는, 그런 사람이 돼야겠다.

- 나를 부인하고 날마다 내 십자가를 지고 예수님을 따라야하는데,
- 그것이 쉽지가 않다.
- 자기 부인의 삶에 대해 더 깊이 생각해 봐야겠다. 

