4.주제 만들기: 
성막 울타리

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
하나님의 지시대로 성막 울타리를 만든 백성들.

7.하나님 찾기(해석)
하나님의 설계대로 성막을 둘러싼 울타리를 이스라엘 백성들이 완공하였다. 

성막으로 들어갈 수 있는 유일한 곳은 ''문''이다. 

그 뜰 문을 생각할 때, 마치 예수님의 외침이 생각난다. 

예수님은 자신을 향하여 이렇게 말씀하셨다. "나는 양의 문이다." 

상징적인 울타리의 용도를 생각할 때 맹수로부터 약한 양들을 보호하는 수단으로 사용한다. 

그리고 외부로부터 부는 강한 바람도 흡수해준다. 

아울러 울타리 안에 성막과 지성소가 있다. 특별히 지성소 안에는 하나님의 임재가 가득한 사실을 받아들인다면 가장 안전한 곳은 울타리 안쪽일 것이다. 

그러므로 믿는 자녀들은 내가 오늘 은혜의 자리인 울타리 안에 있는가를 점검하는 것이 매우 주는지를 여겨진다. 

그러기 위해서는 반드시 길이고 진리요 생명이신 예수님을 통해서만 이루어짐을 알게 된다.

8. 인간 찾기(해석)

9.적용(나):
오직 생명의 ''문'' 되신 예수님과 더욱 동행하기 위하여 힘써야겠다.
오늘 수요 기도모임 때 더욱 간절히 임재를 구해야겠다.

