6.인간 찾기(관찰)
- 아론의 아들 이다말이 모세의 명령대로 재료 목록을 작성함
- 브살렐은 여호와께서 모세에게 명령한 것을 만듦
- 오홀리압이 브살렐과 함께 함
- 성전 건축에 사용된 금은 오늘날 무게로 환산하면 약 1톤이 되고,
- 은은 약 3톤이 넘는다.
- 스무 살 이상 계수된 자가 성전세로 반 세겔씩 냄 

7.하나님 찾기(해석)

8.인간 찾기(해석)
- 하나님의 성막을 짓는 일은 재료 목록을 철저하게 작성하고,
- 하나님의 명령대로 브살렐과 오홀리압이 만들었다.
- 성전은 규모 있게 그리고 정교하게 지어졌다.
- 하나님의 일은 규모 있고 정교하게 해야한다.

- 성전 건축에 사용된 금, 은, 놋의 무게는 오늘날 상상하기 힘든 양이다.
- 여호와 하나님을 얼마나 경외했는지, 알 수 있는 부분이다.

- 스무 살 이상 계수된 자가 성전세로 반 세겔을 낸 것을 속전이다.
- 예수님은 우리 그리스도인의 속전으로 십자가를 지셨다.
- 우리는 예수님의 값으로 대속 받았다.

9.적용(나) 
- 하나님의 일을 할 때 나의 노력이 아닌 하나님의 역사를 보곤 한다.
- 너무나 놀랍고 은혜로운 일이다.
- 그러나 하나님의 역사를 신뢰하고 익숙해지면 일의 준비를 주먹구구로 할 때가 있다.
- 하나님의 자녀가 일을 주먹구구로 해서는 안 되는데, 
- 최선을 다해야 하는데, 그렇지 못한 것을 회개한다.
- 맡기신 일을 할 때는 규모 있고 섬세하게 하도록 노력해야겠다.

