4.주제 만들기: 
흉패

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
하나님의 지시대로 제사장 가슴에 부착할 흉패를 만든 백성들.

7.하나님 찾기(해석)
하나님은 제사장이 입는 에봇의 가슴 부분에 흉패를 부착하도록 설계하셨고 이스라엘 백성들은 그대로 이행하였다. 

특히 흉패 안에는 12개의 각각 다른 보석을 달았는데 12개 지파를 대표하는 이름을 상징한다.

귀한 각자 다른 보석들을 재사장 가슴에 붙였다는 것을 생각하면 하나님은 그들의 백성을 각자 다른 모양으로 빛나도록 창조하심을 느낀다. 

그러므로 하나님의 백성들은 서로 비교하거나 질투 대상이 아닌 주님의 영광을 드러낸다는 같은 목적을 생각할 때 다 소중한 보석 같은 생각을 하게 된다. 

서로 외모나 재정이나 건강 상태나 육체적으로 속한 국가가 달라도 상관없이 백성들은 각기 다른 모양으로 보석처럼 빛나는 존재들인 것을 더욱 깨우친다.

이번에 일본 단기선교를 떠난다. 잘 준비하여 함께 하는 동역자들과 더불어 주님을 빛내도록 나부터 잘 준비해야겠다.

8. 인간 찾기(해석)

9.적용(나):
주님의 빛나는 백성답게 오늘도 잘 살아내야겠다.

10. 영적터치 (단어 또는 구절)
14절: 이 보석들은 이스라엘의 아들들의 이름 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-26', '출애굽기', '39장 21~30절', ' ', '(출애굽기 39장)
21. 청색 끈으로 흉패 고리와 에봇 고리에 꿰어 흉패로 정교하게 짠 에봇 띠 위에 붙여서 에봇에서 벗어지지 않게 하였으니 여호와께서 모세에게 명령하신 대로 하였더라
22.  그가 에봇 받침 긴 옷을 전부 청색으로 짜서 만들되
23. 그 옷의 두 어깨 사이에 구멍을 내고 갑옷 깃 같이 그 구멍 주위에 깃을 짜서 찢어지지 않게 하고
24. 청색 자색 홍색 실과 가는 베 실로 그 옷 가장자리에 석류를 수 놓고
25. 순금으로 방울을 만들어 그 옷 가장자리로 돌아가며 석류 사이사이에 달되
26. 방울과 석류를 서로 간격을 두고 번갈아 그 옷 가장자리로 돌아가며 달았으니 여호와께서 모세에게 명령하신 대로 하였더라
27. 그들이 또 직조한 가는 베로 아론과 그의 아들들을 위하여 속옷을 짓고
28. 세마포로 두건을 짓고 세마포로 빛난 관을 만들고 가는 베 실로 짜서 세마포 속바지들을 만들고
29. 가는 베 실과 청색 자색 홍색 실로 수 놓아 띠를 만들었으니 여호와께서 모세에게 명령하신 대로 하였더라
30. 그들이 또 순금으로 거룩한 패를 만들고 도장을 새김 같이 그 위에 ''여호와께 성결''이라 새기고

