2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
긴 옷/옷/옷 가장자리: 21절 22절 25절 26절 
방울: 25절 26절 
석류: 24절 25절 
세마포: 28절(2)

4.주제 만들기: 
제사장의 긴 옷과 장식류

5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
하나님의 지시대로 제사장 긴 옷에 부착할 방울과 석류를 부착함

7.하나님 찾기(해석)
하나님은 제사장 긴 옷 하단부에 석류와 방울을 달게 하셨다. 

긴 옷의 색은 청색인 것을 추측하면 하늘 또는 천국을 연상케 하는 듯하다. 

또한 석류의 의미는 ''풍요로움''이다. 반면 방울의 용도는 제사장이 거룩한 지성소에 들어갔을 때 생사를 확인하는 용도이다. 

그러면 하나님은 왜 하늘나라 와 풍요롭고 심판적 상징을 동시에 조화를 이루며 부착하도록 하셨을까?

아마도 하나님은 제사장의 옷과 장식류를 통하여 도래할 하나님 나라의 풍성함과 동시의 땅에서 절대 주권자이신 하나님의 통치에 순종과 충성할 것을 내포하고 있는 것 같다. 

그러면서 생각되는 것은 ‘공의’와 ‘사랑’을 동시에 실천하신 예수님을 예표 하는 듯하다. 

아울러 제사장 머리 면류관 패에 ''여호와께 성결"이라는 글귀를 쓰라고 하신 것을 보면 하나님 스스로가 얼마나 거룩하심을 강조하셨다는 것을 알 수 있다.

8. 인간 찾기(해석)

9.적용(나):
천국복음이 가장 큰 축복이기에 더욱 열심히 전도해야겠다. 아울러 5월에 있을 일본 단기전도 여행을 위하여 더욱 기도로 준비해야겠다.

10. 영적터치 (단어 또는 구절)
26절: 방울과 석류를 서로 간격을 두고 번갈아 그 옷 가장자리로 돌아가며 달았으니 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-27', '출애굽기', '39장 31~43절', '하나님의 명령대로 순종할 때 받게되는 축복', '[출39:31-43]
31 그 패를 청색 끈으로 관 전면에 달았으니 여호와께서 모세에게 명령하신 대로 하였더라
32 이스라엘 자손이 이와 같이 성막 곧 회막의 모든 역사를 마치되 여호와께서 모세에게 명령하신 대로 다 행하고
33 그들이 성막을 모세에게로 가져왔으니 곧 막과 그 모든 기구와 그 갈고리들과 그 널판들과 그 띠들과 그 기둥들과 그 받침들과
34 붉은 물을 들인 숫양의 가죽 덮개와 해달의 가죽 덮개와 가리는 휘장과
35 증거궤와 그 채들과 속죄소와
36 상과 그 모든 기구와 진설병과
37 순금 등잔대와 그 잔 곧 벌여놓는 등잔대와 그 모든 기구와 등유와
38 금 제단과 관유와 향기로운 향과 장막 휘장 문과
39 놋 제단과 그 놋 그물과 그 채들과 그 모든 기구와 물두멍과 그 받침과
40 뜰의 포장들과 그 기둥들과 그 받침들과 뜰 문의 휘장과 그 줄들과 그 말뚝들과 성막 곧 회막에서 사용할 모든 기구와
41 성소에서 섬기기 위한 정교한 옷 곧 제사 직분을 행할 때에 입는 제사장 아론의 거룩한 옷과 그의 아들들의 옷이라
42 여호와께서 모세에게 명령하신 대로 이스라엘 자손이 모든 역사를 마치매
43 모세가 그 마친 모든 것을 본즉 여호와께서 명령하신 대로 되었으므로 모세가 그들에게 축복하였더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 명령하신 대로(31,32,42,43절)
- 여호와(31,32,42,43절)
- 모세(31,32,33,42,43절)
- 모든 역사를 마침(32,43절)

4. 주제만들기: 하나님의 명령대로 순종할 때 받게되는 축복

5. 하나님 찾기 (관찰)
- 하나님은 인간에게 성막과 성소 등을 만들도록 명령하셨다.

6. 인간 찾기 (관찰)
- 하나님께서 명령하신대로 만들어 모세에게 가져감
- 하나님의 명령대로 만든 것을 보고 축복함

7. 하나님 찾기 (해석) 
- 하나님은 인간이 자신에게 순종하기 원하신다. 우리는 연약한 존재이므로 언제든 하나님을 벗어나고자 하는 죄성이 있다. 
- 그러나 하나님께선 죄많은 우리를 사랑하셔서 자신의 테두리 안에 머물 수 있도록 도와주신다. 
- 우리를 정밀하게 훈련시켜 하나님 앞에 온전히 설 수 있도록 도와주신다. 그 방법은 저마다 다를 것이다. 어떤 사람은 등잔대와 같이, 어떤 사람은 그릇과 같이...
- 하나님께서 원하시는 것은 단, 하나 순종이다.

8. 인간(해석):
- 인간이 하나님의 명령대로 순종하니 하나님께선 축복을 내리셨다. 
- 이집트에서 살며 억압만 받아오던 이스라엘 백성은 복을 주시는 하나님께 영광과 찬송을 올렸을 것이다.
- 이스라엘 백성이 하나님을 모세와 같은 믿음으로 바라보았다면 어떻게 되었을까? 
- 이스라엘 백성은 모세에게 받은 축복을 자신들의 기준으로 해석했는지도 모른다. 
- 그것이 불신앙이 되었을 것이다. 

9. 적용(나):
- 하나님에게 순종하기만 하면 된다. 이것이 가장 어려운 일이지만 그럴 수 있도록 믿음 더해주시도록 기도해야겠다.
- 하나님께서 주신 복을 내 뜻대로 해석하지 않도록 주의해야겠다.

10. 영적터치(단어/구절): 명령대로

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-28', '출애굽기', '40장 1~10절', '성막을 세워라', '출애굽기 40장
1   여호와께서 모세에게 말씀하여 이르시되
2   너는 첫째 달 초하루에 성막 곧 회막을 세우고
3   또 증거궤를 들여놓고 또 휘장으로 그 궤를 가리고
4   또 상을 들여놓고 그 위에 물품을 진설하고 등잔대를 들여놓아 불을 켜고
5   또 금 향단을 증거궤 앞에 두고 성막 문에 휘장을 달고
6   또 번제단을 회막의 성막 문 앞에 놓고
7   또 물두멍을 회막과 제단 사이에 놓고 그 속에 물을 담고
8   또 뜰 주위에 포장을 치고 뜰 문에 휘장을 달고
9   또 관유를 가져다가 성막과 그 안에 있는 모든 것에 발라 그것과 그 모든 기구를 거룩하게 하라 그것이 거룩하리라
10   너는 또 번제단과 그 모든 기구에 발라 그 안을 거룩하게 하라 그 제단이 지극히 거룩하리라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
성막: 2, 5, 6, 9
회막: 2, 6, 7
증거궤: 3, 5
휘장: 3, 5, 8
번제단: 6, 7, 10(2)
모든: 9(2), 10
기구: 9, 10
거룩: 9(2), 10(2)

4.주제 만들기: 성막을 세워라

5.하나님 찾기(관찰)
- 모세에게 첫째 달 초하루에 성막을 세우라 명하심
- 성막을 세우고 성막을 채우는 순서에 대해 말씀하심

6.인간 찾기(관찰)
- 하나님의 말씀을 듣는 모세

7.하나님 찾기(해석)
- 한 해의 첫 번째 날을 성막을 세우는 날로 정하셨다.
- 하나님의 때는 하나님이 정하시면 언제나 옳지만,
- 하나님은 특별히 한 해의 첫날을 성막을 세우는 날로 정하셨다.
- 이 것은 한 해의 첫날을 의미 있는 날로 인식하는 인간의 생각을 사용하신 것일 수 있다.
- 그렇다면 우리는 한 해의 첫날을 하나님을 예배하는 행위로, 
- 하나님의 임재를 간절히 바라는 기도로 시작하는 것은 의미 있는 일이 될 것이다.

- 성막을 세우고 나서 가장 먼저 하는 일은 증거궤를 들여놓는 것이다.
- 증거궤를 들여놓고 휘장으로 그 궤를 가리게 하였다.
- 가장 중요한 것을 가장 먼저 하게 하시고, 다른 것들을 놓게 하셨다.
- 그리고 성막 뜰에 울타리를 치고 정문에 휘장을 달게 하셨다.
- 우리는 일을 할 때 순서를 정해놓고 할 필요가 있으며,
- 그 일의 순서는 중요한 일을 먼저 하는 것이 좋을 것이다.

- 성막과 모든 것에 관유를 바르게 하시며,
- 관유가 발라진 성막과 모든 기구가 거룩할 것이라 말씀하셨다.

8.인간 찾기(해석)

9.적용(나) 
- 하나님의 구원의 때를 잠잠히 바라며 기다릴 줄 아는 자가 되고 싶다.
- 나는 조급하다. 많이 조급하다.
- 잠잠히 하나님의 때를 기다려야 한다.

- 일을 할 때 늘 주님의 임재와 도우심을 바라며,
- 일의 순서를 정하고, 그 순서대로 일하려고 노력해야겠다. 

