2025년 4월30일 
출애굽기 40장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
거룩: 11절 13절 
제사장: 13절 15절 
제사장의 직분: 13절 15절
성막: 17절 18절 19절
기름을 부음: 13절 15절
명령하신 대로: 16절 19절

4.주제 만들기: 
제사장의 거룩함을 원하시는 여호와.

5.하나님 찾기 (관찰)
모세에게 제사장 아론과 그의 아들들이 행할일들(물로 씻고 기름붓는 일)을 명령하시는 여호와.

6.인간 찾기(관찰)
하나님의 명령대로 순종하는 모세.

7.하나님 찾기(해석)
여호와께서 모세에게 명령하신 것처럼 모세는 제사장인 아론과 그의 아들들을 대상으로 물로 씻기고 기름을 붓는다. 

기름 부음과 물로 씻음의 의미는 거룩함의 의미와 구별됨을 나타난다. 

이 행위를 생각할 때 현대를 사는 많은 주의 종은 세상과 구분될 정도로 거룩함을 추구해야 함을 느낀다. 

이시대를 사는 많은 나를 포함한 교회 성직자들은 과연 거룩한 삶을 살아가고 있는가?

사실 ''만인 제사장'' 신앙을 통하여 모든 믿는 사람들까지도 그러한 삶을 성경은 요청하고있다. 

 거룩하고 구별된 삶을 살도록 하는 것은 순전히 하나님의 뜻이고 명령이라 본다면 그대로 순종하며 산다는 것은 오직 주님과 깊은 교제 안에서 그 분께 오직 거할 때만이 가능하다는 것을 깨우친다. 

그러한 시각에서 본다면 공중 예배가 얼마나 중요한지 일깨움을 받는다. 그럴 뿐만 아니라 삶 전체가 예배의 삶을 이루도록 사는 것이 매우 중요함을 깨우친다!

8. 인간 찾기(해석)

9.적용(나):
주의 종으로 더욱 경건하며 거룩한 삶을 살도록 힘써야겠다.

