5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
데오빌로에게 예수님에 관하여 편지를 쓰는 누가.
의인이었던 제사장 사가랴와 아내 엘리사벳.
그들에게는 아직 아기가 없었다.

7.하나님 찾기(해석)

8. 인간 찾기(해석)
사도바울의 동역자요 직업이 의사였던 ''누가''는 각하 ‘데오빌로’를 대상으로 복음서의 하나인 누가복음을 저술하였다. 

아마도 그에게 사실적 복음을 알리기 위해 힘썼던 것 같다. 

저자인 ‘누가’는 복음적인 삶을 살았고 예수님에 관하여 알리기 위해 힘쓴 것도 알 수 있다. 

그러한 마음을 보신 성령 하나님은 그를 저술가로 사용하시어 모든 사람에게 복음을 알리신 것 같다.

한편 당시 제사장이었던 ‘사가랴’와 아내 ‘엘리사벳’은 흠이 없을 정도로 의인 부부였다고 기록되어 있다. 

그런데 노년이 다가왔음에도 그들에게는 아직 아기가 없었다. 하나님께 칭찬받는 사람이라도 이 땅에서는 누구나 시련이 있을 수 있음을 알 수 있다.

그런데도 묵묵히 자신의 제사장 직분을 성실히 하는 모습을 볼 수 있다.

9.적용(나):
