7. 하나님 찾기 (해석) 
- 하나님께선 성막에 임재하셔서 영광이 충만하게 되었다. 하나님이 거하는 곳은 거룩한 곳이다. 거룩한 성막을 만들기 위해 이스라엘 백성은 얼마나 많은 노력을 기울였을까? 이 시대를 살아가는 우리가 깨닫고 느껴야할 점이다.
- 하나님께선 이스라엘 백성을 낮에는 구름 기둥으로, 밤에는 불기둥으로 인도하셨다. 이것은 하나님의 임재 가운데 이루어진 것으로 이스라엘 백성의 삶의 모든 것을 주관하시는 분은 하나님이시다. 하나님이 임재하신 가운데 이스라엘 백성은 하나님의 인도하심을 따라 살아갈 수 있게 된다.

8. 인간(해석):

9. 적용(나): 
- 하나님의 말씀에 순종하고, 내가 만들어야할 성전을 거룩하게 하여 하나님의 임재와 영광이 가득하도록 해야겠다. 많은 노력이 필요한 부분이다. 하나님의 은혜를 전적으로 구해야겠다.
- 하나님의 택하심을 받아 하나님의 성막을 거룩하게 만들 수 있게 되었다. 아직 자신이 거룩한 성전임을 모르는 사람들에게 예수님을 힘써 전해야겠다.

10. 영적터치(단어/구절)
- 여호와의 영광이 성막에 충만하매

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-03', '누가복음', '1장 11~20절', ' ', '(누가복음 1장)
11. 주의 사자가 그에게 나타나 향단 우편에 선지라
12. 사가랴가 보고 놀라며 무서워하니
13. 천사가 그에게 이르되 사가랴여 무서워하지 말라 너의 간구함이 들린지라 네 아내 엘리사벳이 네게 아들을 낳아 주리니 그 이름을 요한이라 하라
14. 너도 기뻐하고 즐거워할 것이요 많은 사람도 그의 태어남을 기뻐하리니
15. 이는 그가 주 앞에 큰 자가 되며 포도주나 독한 술을 마시지 아니하며 모태로부터 성령의 충만함을 받아
16. 이스라엘 자손을 주 곧 그들의 하나님께로 많이 돌아오게 하겠음이라
17. 그가 또 엘리야의 심령과 능력으로 주 앞에 먼저 와서 아버지의 마음을 자식에게, 거스르는 자를 의인의 슬기에 돌아오게 하고 주를 위하여 세운 백성을 준비하리라
18. 사가랴가 천사에게 이르되 내가 이것을 어떻게 알리요 내가 늙고 아내도 나이가 많으니이다
19. 천사가 대답하여 이르되 나는 하나님 앞에 서 있는 가브리엘이라 이 좋은 소식을 전하여 네게 말하라고 보내심을 받았노라
20. 보라 이 일이 되는 날까지 네가 말 못하는 자가 되어 능히 말을 못하리니 이는 네가 내 말을 믿지 아니함이거니와 때가 이르면 내 말이 이루어지리라 하더라

