누가복음 1장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
주의사자/천사/가브리엘: 11절 13절 18절 19절
사가랴: 11절 12절 13절 18절 
무서워함: 12절 13절 
말 못함: 20절(2)
기뻐함:14절(2)

4.주제 만들기: 
좋은소식을 전하는 천사 가브리엘

5.하나님 찾기 (관찰)
천사 가브리엘을 제사장 사가랴에 보낸 하나님.
그에게 자녀를 주실 좋은 소식을 예고함.
아들의 이름을 ''요한''이라 미리 정해주심.

6.인간 찾기(관찰)
천사 가브리엘을 보고 무서워하는 제사장 사가랴.
자녀를 준다고 하는말을 믿지못하는 사가랴(스스로 신체적 나이를 가늠함)

7.하나님 찾기(해석)
하나님은 불가능처럼 보이는 일이라도 모든 것을 가능케 하실수있는 전능하신 분이시다.

8. 인간 찾기(해석)
하나님이 보낸 천사장 가브리엘이 제사장 사가랴에게 기쁜 소식을 전했다. 

내용인즉 노년인 사가랴와 아내 엘리사벳에게 아기를 준다는 것이었다. 

내용을 들은 사가랴는 생물학적으로 임신이 가능하지 않은 노년인지라 쉽게 받아들이지 못한 듯하다. 

도리어 가브리엘은 확신을 두고 말하며 믿지 못하는 사가랴를 향하여 아기를 갖기 전까지 일시적으로 말을 못 하게 하겠다고 했다. 

그런데 개인적으로 궁금한 것은 12절에 보면 "너의 간구가 들린지라" 기록된 것을 보면 평생 제사장 사가랴가 얼마나 아기를 갖고 싶었는지 알 수 있다.  

평소에 하나님께 간구하는 기도는 반드시 때가 되면 하나님 때에 맞추어 응답하신다는 것이다. 

다만 기도를 구하는 자의 때보다 더 좋은 때 역사하심을 생각해보면 기다림이 반드시 동반되어야 함을 느낀다. 

9.적용(나):
주님께 간구하는 것은 하나님의 때에 역사됨을 믿는다. 그러므로 주변의 영혼 구원을 위하여 늘 쉬지않고 기도에 힘써야겠다.

10. 영적터치 (단어 또는 구절)
13절: 너의 간구함이 들린지라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-05-04', '누가복음', '1장 21~30절', '은혜를 입은 마리아', '[눅1:21-30]
21 백성들이 사가랴를 기다리며 그가 성전 안에서 지체함을 이상히 여기더라
22 그가 나와서 그들에게 말을 못하니 백성들이 그가 성전 안에서 환상을 본 줄 알았더라 그가 몸짓으로 뜻을 표시하며 그냥 말 못하는 대로 있더니
23 그 직무의 날이 다 되매 집으로 돌아가니라
24 이 후에 그의 아내 엘리사벳이 잉태하고 다섯 달 동안 숨어 있으며 이르되
25 주께서 나를 돌보시는 날에 사람들 앞에서 내 부끄러움을 없게 하시려고 이렇게 행하심이라 하더라
26 여섯째 달에 천사 가브리엘이 하나님의 보내심을 받아 갈릴리 나사렛이란 동네에 가서
27 다윗의 자손 요셉이라 하는 사람과 약혼한 처녀에게 이르니 그 처녀의 이름은 마리아라
28 그에게 들어가 이르되 은혜를 받은 자여 평안할지어다 주께서 너와 함께 하시도다 하니
29 처녀가 그 말을 듣고 놀라 이런 인사가 어찌함인가 생각하매
30 천사가 이르되 마리아여 무서워하지 말라 네가 하나님께 은혜를 입었느니라

