- 은혜(28,30절)

3. 반복단어 찾기(형광펜 추천)

4. 주제만들기: 은혜를 입은 마리아

5. 하나님 찾기 (관찰)
- 처녀 마리아에게 천사 가브리엘을 보내심
- 마리아와 함께하시고 은혜를 주심

6. 인간 찾기 (관찰)
- 사가랴는 말을 못하게 되었고, 엘리사벳은 잉태 후 다섯달 동안 숨어지냄
- 마리아는 천사의 말을 듣고 놀람

7. 하나님 찾기 (해석) 
- 하나님의 때에 이르러 천사 가브리엘을 통해 마리아를 찾아가게 하셨다. 하나님의 완벽성을 볼 수 있는데 마리아 이전에 엘리사벳에게 마리와 같이 잉태하는 경험을 하게 하셔서 마리아가 겪을 혼란을 예방해주셨다. 
- 하나님의 능력, 하나님의 일하심은 우리가 해석할 수 없다. 우리가 예측할 수 없는 일로 우리를 인도하시는 하나님은 이 세상 유일한 참 신이시다.

8. 인간(해석):
- 엘리사벳은 잉태 후 숨어지내며 하나님의 때에 자신의 수치를 없애주셨다며 감격했다. 얼마나 자녀를 꿈꿨을지 생각해본다. 더불어 우리에게 자녀를 주신 하나님께 감사드리며, 아이가 생기지 않았을 때 감정을 다시 떠올려본다.
- 마리아에게 천사 가브리엘이 찾아갔다. 천사가 나타났을 때 놀랄 법도 하지만 마리아는 오히려 가브리엘의 말에 주목했다. 은혜를 받은 것과 하나님께서 함께하신다는 말에 그 뜻을 생각해보는 마리아의 신앙이 얼마나 깊은지 생각해볼 수 있다.

9. 적용(나): 
- 바라고 소망하는 것이 하나님의 뜻에 합한다면 하나님께서 반드시 이루신다. 우리가 소망하는 것들이 하나님께서 바라시는 길인지 생각해보고 올바른 길을 걸어갈 수 있도록 지혜를 구해야겠다. 
- 하나님께서 찾아오셨을 때 준비된 사람이 되도록 신앙 훈련에 더욱 힘써야겠다.

10. 영적터치(단어/구절)
- 네가 하나님께 은혜를 입었느니라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);